59	template <>
60	Status CreateOperation(const infer::MultiLatentAttentionParam &opParam, Operation **operation)
61	{
62	    if (operation == nullptr) {
63	        return ERROR_INVALID_PARAM;
64	    }
65	    ATB_LOG(INFO) << "CreateOperation with MultiLatentAttentionParam: " << OpParamToJson(opParam);
66	    if (!GetSingleton<Config>().Is910B()) {
67	        ATB_LOG(ERROR) << "only support Atlas 800I A2/A3 Inference Product";
68	        return ERROR_INVALID_PARAM;
69	    }
70	    if (!ParamRangeCheck(opParam)) {
71	        return ERROR_INVALID_PARAM;
72	    }
73	    if (opParam.calcType == infer::MultiLatentAttentionParam::CalcType::CALC_TYPE_PREFILL) {
74	        if (!ParamPrefillCheck(opParam)) {
75	            return ERROR_INVALID_PARAM;
76	        }
77	    } else {
78	        if (!ParamCheck(opParam)) {
79	            return ERROR_INVALID_PARAM;
80	        }
81	    }
82	    OP_PARAM_RSV_CHECK(opParam);
83	    *operation = new (std::nothrow) MultiLatentAttentionOperation(opParam);
84	    if (*operation == nullptr) {
85	        ATB_LOG(ERROR) << "failed to new MultiLatentAttentionOperation";
86	        return ERROR_OUT_OF_HOST_MEMORY;
87	    }
88	    return NO_ERROR;
89	}
