91	static bool ParamCheck(const infer::MultiLatentAttentionParam &opParam)
92	{
93	    if (opParam.headNum != 8 && opParam.headNum != 16 && opParam.headNum != 32 &&  // 8, 16, 32: headNum
94	        opParam.headNum != 64 && opParam.headNum != 128) {                         // 64, 128: headNum
95	        ATB_LOG(ERROR) << "headNum should be {8,16,32,64,128}";
96	        return false;
97	    }
98	    if (opParam.kvHeadNum != 1) {
99	        ATB_LOG(ERROR) << "kvHeadNum should be 1, only support MQA";
100	        return false;
101	    }
102	    if (opParam.cacheMode == infer::MultiLatentAttentionParam::CacheMode::KVCACHE) {
103	        ATB_LOG(ERROR) << "dont support cacheMode KVCACHE yet";
104	        return false;
105	    }
106	    if ((opParam.calcType != infer::MultiLatentAttentionParam::CalcType::CALC_TYPE_SPEC &&
107	         opParam.calcType != infer::MultiLatentAttentionParam::CalcType::CALC_TYPE_SPEC_AND_RING) &&
108	        opParam.maskType != infer::MultiLatentAttentionParam::MaskType::UNDEFINED) {
109	        ATB_LOG(ERROR) << "only mtp(CALC_TYPE_SPEC) support mask";
110	        return false;
111	    }
112	    if ((opParam.calcType == infer::MultiLatentAttentionParam::CalcType::CALC_TYPE_SPEC ||
113	         opParam.calcType == infer::MultiLatentAttentionParam::CalcType::CALC_TYPE_SPEC_AND_RING) &&
114	        opParam.maskType == infer::MultiLatentAttentionParam::MaskType::MASK_TYPE_SWA_NORM) {
115	        ATB_LOG(ERROR) << "MLA decode (CALC_TYPE_SPEC) does not support SWA_NORM mask. "
116	                        << "Kernel SoftmaxStage1 only handles mask_type=3 (LOOK_AHEAD) and 4 (MASK_FREE). "
117	                        << "Use CALC_TYPE_PREFILL for SWA_NORM or set maskType to MASK_FREE.";
118	        return false;
119	    }
120	    if ((opParam.cacheMode == infer::MultiLatentAttentionParam::CacheMode::INT8_NZCACHE) &&
121	        (opParam.calcType == infer::MultiLatentAttentionParam::CalcType::CALC_TYPE_RING ||
122	         opParam.calcType == infer::MultiLatentAttentionParam::CalcType::CALC_TYPE_SPEC_AND_RING) &&
123	        (opParam.maskType != infer::MultiLatentAttentionParam::MaskType::UNDEFINED)) {
124	        ATB_LOG(ERROR) << "int8nz lse not support mask";
125	        return false;
126	    }
127	    if (opParam.maskUseStatusType <
128	            infer::MultiLatentAttentionParam::MaskUseStatusType::MASK_USE_STATUS_TYPE_UNDEFINED ||
129	        opParam.maskUseStatusType >= infer::MultiLatentAttentionParam::MaskUseStatusType::MASK_USE_STATUS_TYPE_MAX) {
130	        ATB_LOG(ERROR)
131	            << "MLA only support MASK_USE_STATUS_TYPE_UNDEFINED and MASK_USE_STATUS_TYPE_BATCH_MASK, but got: "
132	            << opParam.maskUseStatusType;
133	        return false;
134	    }
135	    if (opParam.maskUseStatusType == infer::MultiLatentAttentionParam::MaskUseStatusType::MASK_USE_STATUS_TYPE_BATCH_MASK) {
136	        if (opParam.calcType != infer::MultiLatentAttentionParam::CalcType::CALC_TYPE_SPEC_AND_RING) {
137	            ATB_LOG(ERROR) << "MLA only supports maskUseStatus in mtp with ring (CALC_TYPE_SPEC_AND_RING), but got calcType: " << opParam.calcType;
138	            return false;
139	        }
140	    }
141	    if (opParam.maskType == infer::MultiLatentAttentionParam::MaskType::MASK_TYPE_SWA_NORM) {
142	        if (opParam.windowSize <= 0) {
143	            ATB_LOG(ERROR) << "windowSize in swa mode should be greater than 0";
144	            return false;
145	        }
146	    }
147	    return true;
148	}
