150	static bool ParamRangeCheck(const infer::MultiLatentAttentionParam &opParam)
151	{
152	    if (opParam.qkScale <= 0 || opParam.qkScale > 1) {
153	        ATB_LOG(ERROR) << "qkScale should > 0 and <= 1";
154	        return false;
155	    }
156	    if (opParam.maskType < infer::MultiLatentAttentionParam::MaskType::UNDEFINED ||
157	        opParam.maskType > infer::MultiLatentAttentionParam::MaskType::MASK_TYPE_SWA_NORM) {
158	        ATB_LOG(ERROR) << "invalid maskType";
159	        return false;
160	    }
161	    if (opParam.calcType < infer::MultiLatentAttentionParam::CalcType::CALC_TYPE_UNDEFINED ||
162	        opParam.calcType > infer::MultiLatentAttentionParam::CalcType::CALC_TYPE_PREFILL) {
163	        ATB_LOG(ERROR) << "invalid calcType";
164	        return false;
165	    }
166	    if (opParam.cacheMode > infer::MultiLatentAttentionParam::CacheMode::NZCACHE) {
167	        ATB_LOG(ERROR) << "invalid cacheMode";
168	        return false;
169	    }
170	    return true;
171	}
