173	static bool ParamPrefillCheck(const infer::MultiLatentAttentionParam &opParam)
174	{
175	    if (opParam.headNum < 1 || opParam.headNum > 128) { // 128: headNum
176	        ATB_LOG(ERROR) << "headNum should be >= 1 and <= 128";
177	        return false;
178	    }
179	    if (opParam.maskType != infer::MultiLatentAttentionParam::MaskType::MASK_TYPE_CAUSAL_MASK) {
180	        if (opParam.headNum != opParam.kvHeadNum) {
181	            ATB_LOG(ERROR) << "Prefill, headNum should be equal to kvHeadNum";
182	            return false;
183	        }
184	    }
185	    if (opParam.maskType != infer::MultiLatentAttentionParam::MaskType::UNDEFINED &&
186	        opParam.maskType != infer::MultiLatentAttentionParam::MaskType::MASK_TYPE_MASK_FREE &&
187	        opParam.maskType != infer::MultiLatentAttentionParam::MaskType::MASK_TYPE_CAUSAL_MASK &&
188	        opParam.maskType != infer::MultiLatentAttentionParam::MaskType::MASK_TYPE_SWA_NORM) {
189	        ATB_LOG(ERROR) << "Prefill, maskType support UNDEFINED, MASK_TYPE_MASK_FREE and MASK_TYPE_SWA_NORM";
190	        return false;
191	    }
192	    if (opParam.cacheMode != infer::MultiLatentAttentionParam::CacheMode::KROPE_CTKV) {
193	        ATB_LOG(ERROR) << "Prefill, cacheMode should be KROPE_CTKV";
194	        return false;
195	    }
196	    if (opParam.maskType == infer::MultiLatentAttentionParam::MaskType::MASK_TYPE_SWA_NORM) {
197	        if (opParam.windowSize <= 0) {
198	            ATB_LOG(ERROR) << "Prefill, windowSize in swa mode should be greater than 0";
199	            return false;
200	        }
201	    }
202	    return true;
203	}
