205	MultiLatentAttentionOperation::MultiLatentAttentionOperation(const infer::MultiLatentAttentionParam &param)
206	    : OperationBase("MultiLatentAttentionOperation"), param_(param)
207	{
208	    std::string opIrKeyStr;
209	    opIrKeyStr += "MultiLatentAttentionOperation";
210	    if (param_.maskType != infer::MultiLatentAttentionParam::MaskType::UNDEFINED &&
211	        param_.maskType != infer::MultiLatentAttentionParam::MaskType::MASK_TYPE_CAUSAL_MASK) {
212	        opIrKeyStr += "Mask";
213	    }
214	    if (param_.calcType == infer::MultiLatentAttentionParam::CalcType::CALC_TYPE_SPEC || param_.
215	                      calcType == infer::MultiLatentAttentionParam::CalcType::CALC_TYPE_SPEC_AND_RING) {
216	        opIrKeyStr += "Qlens";
217	    }
218	    if (param_.calcType == infer::MultiLatentAttentionParam::CalcType::CALC_TYPE_RING || param_.
219	                      calcType == infer::MultiLatentAttentionParam::CalcType::CALC_TYPE_SPEC_AND_RING) {
220	        opIrKeyStr += "IsRing";
221	    }
222	    if (param_.cacheMode == infer::MultiLatentAttentionParam::CacheMode::INT8_NZCACHE) {
223	        opIrKeyStr += "Int8Nz";
224	    }
225	    if (param_.cacheMode == infer::MultiLatentAttentionParam::CacheMode::NZCACHE) {
226	        opIrKeyStr += "Nz";
227	    }
228	    if (param_.calcType == infer::MultiLatentAttentionParam::CalcType::CALC_TYPE_PREFILL) {
229	        opIrKeyStr += "Prefill";
230	    }
231	    if (param_.maskUseStatusType ==
232	        infer::MultiLatentAttentionParam::MaskUseStatusType::MASK_USE_STATUS_TYPE_BATCH_MASK) {
233	        opIrKeyStr += "MaskUseStatus";
234	    }
235	    operationIr_ = GetSingleton<AtbOperationIrCfg>().GetOperationIr(opIrKeyStr);
236	}
