240	uint32_t MultiLatentAttentionOperation::GetInputNum() const
241	{
242	    uint32_t intensorNumBase = IN_TENSOR_NUM;
243	    if (param_.maskType != infer::MultiLatentAttentionParam::MaskType::UNDEFINED &&
244	        param_.maskType != infer::MultiLatentAttentionParam::MaskType::MASK_TYPE_CAUSAL_MASK) {
245	        intensorNumBase++; // 1: mask
246	    }
247	    if (param_.calcType == infer::MultiLatentAttentionParam::CalcType::CALC_TYPE_PREFILL) {
248	        intensorNumBase++; // 1: vNope, qSeqlen替换blocktables
249	    }
250	    if (param_.calcType == infer::MultiLatentAttentionParam::CalcType::CALC_TYPE_SPEC || param_.
251	                      calcType == infer::MultiLatentAttentionParam::CalcType::CALC_TYPE_SPEC_AND_RING) {
252	        // MTP
253	        intensorNumBase++; // 1: qSeqlen
254	    }
255	    if (param_.cacheMode == infer::MultiLatentAttentionParam::CacheMode::INT8_NZCACHE) {
256	        intensorNumBase += 2; // 2: qDescale, kDescale
257	    }
258	    if (param_.maskUseStatusType ==
259	        infer::MultiLatentAttentionParam::MaskUseStatusType::MASK_USE_STATUS_TYPE_BATCH_MASK) {
260	        intensorNumBase++; // 1: maskUseStatus
261	    }
262	    return intensorNumBase;
263	}
