272	Status MultiLatentAttentionOperation::InferShapeImpl(const SVector<TensorDesc> &inTensorDescs,
273	                                                     SVector<TensorDesc> &outTensorDescs) const
274	{
275	    outTensorDescs.at(0) = inTensorDescs.at(0);
276	    outTensorDescs.at(0).dtype = inTensorDescs.at(1).dtype;
277	    if ((param_.calcType == infer::MultiLatentAttentionParam::CalcType::CALC_TYPE_RING || param_.
278	                      calcType == infer::MultiLatentAttentionParam::CalcType::CALC_TYPE_SPEC_AND_RING)) {
279	        outTensorDescs.at(1) = outTensorDescs.at(0);
280	        if (param_.cacheMode == infer::MultiLatentAttentionParam::CacheMode::INT8_NZCACHE) {
281	            outTensorDescs.at(1).dtype = ACL_FLOAT;
282	        }
283	        outTensorDescs.at(1).shape.dims[2] = 1; // 2: dim2
284	    }
285	    return NO_ERROR;
286	}
