300	Status MultiLatentAttentionOperation::SetupCheckImpl(const SVector<Tensor> &inTensors,
301	                                                     const SVector<Tensor> &outTensors) const
302	{
303	    (void)outTensors;
304	    SVector<TensorDesc> inTensorDescs = {};
305	    SVector<TensorDesc> outTensorsDescs = {};
306	    OperationUtil::InTensorsToInTensorDescs(inTensors, inTensorDescs);
307	    OperationUtil::InTensorsToInTensorDescs(outTensors, outTensorsDescs);
308	    if (param_.calcType == infer::MultiLatentAttentionParam::CalcType::CALC_TYPE_PREFILL) {
309	        Status st = InTensorDimCheckPrefill(inTensorDescs);
310	        if (st != NO_ERROR) {
311	            return st;
312	        }
313	        st = TensorCheck::TensorDescsEqual(inTensors.at(0).desc, outTensors.at(0).desc);
314	        if (st == ERROR_INVALID_TENSOR_SIZE) {
315	            ATB_LOG(ERROR) << GetLogPrefix() << "outTensor0 dimNum and inTensor0 dimNum should be equal";
316	        } else if (st == ERROR_INVALID_TENSOR_DIM) {
317	            ATB_LOG(ERROR) << GetLogPrefix() << "outTensor0 dims and inTensor0 dims should be same";
318	        }
319	        return st;
320	    }
321	    Status st = DimCheck(inTensorDescs);
322	    if (st != NO_ERROR) {
323	        return st;
324	    }
325	    if ((param_.calcType == infer::MultiLatentAttentionParam::CalcType::CALC_TYPE_RING ||
326	         param_.calcType == infer::MultiLatentAttentionParam::CalcType::CALC_TYPE_SPEC_AND_RING) &&
327	        param_.maskType == infer::MultiLatentAttentionParam::MaskType::UNDEFINED &&
328	        param_.cacheMode == infer::MultiLatentAttentionParam::CacheMode::INT8_NZCACHE) {
329	        st = DimCheckInt8NzLse(inTensorDescs, outTensorsDescs);
330	    }
331	    if (st != NO_ERROR) {
332	        return st;
333	    }
334	    return NO_ERROR;
335	}
