337	Status MultiLatentAttentionOperation::QKVDimCheck(const SVector<TensorDesc> &inTensorDesc) const
338	{
339	    int64_t numTokens = inTensorDesc.at(0).shape.dims[0];
340	    int64_t numBlocks = inTensorDesc.at(KVCACHE_INDEX).shape.dims[0];
341	    int64_t blockSize = inTensorDesc.at(KVCACHE_INDEX).shape.dims[1];
342	    if (blockSize != DECODER_BLOCK_SIZE) { // decoder blockSize
343	        ATB_LOG(ERROR) << GetLogPrefix() << "decoder blockSize should be " << DECODER_BLOCK_SIZE << ", but got "
344	                       << blockSize;
345	        return ERROR_INVALID_TENSOR_DIM;
346	    }
347	    if (inTensorDesc.at(1).shape.dims[0] != numTokens) {
348	        ATB_LOG(ERROR) << GetLogPrefix() << "dim 0 of query(intensor0) and queryRope(intensor1) should be same";
349	        return ERROR_INVALID_TENSOR_DIM;
350	    }
351	    if (inTensorDesc.at(KVCACHE_ROPE_INDEX).shape.dims[0] != numBlocks ||
352	        inTensorDesc.at(KVCACHE_ROPE_INDEX).shape.dims[1] != blockSize) {
353	        ATB_LOG(ERROR) << GetLogPrefix()
354	                       << "dim 0 and dim 1 of kvCache(intensor2) and kvCacheRope(intensor3) should be same";
355	        return ERROR_INVALID_TENSOR_DIM;
356	    }
357	    if (inTensorDesc.at(KVCACHE_INDEX).shape.dims[2] != param_.kvHeadNum ||      // 2: dim 2
358	        inTensorDesc.at(KVCACHE_ROPE_INDEX).shape.dims[2] != param_.kvHeadNum) { // 2: dim 2
359	        ATB_LOG(ERROR) << GetLogPrefix() << "dim 1 of kvCache(intensor2) and kvCacheRope(intensor3) equal to kvHeadNum";
360	        return ERROR_INVALID_TENSOR_DIM;
361	    }
362	
363	    if (inTensorDesc.at(0).shape.dims[1] != param_.headNum || inTensorDesc.at(1).shape.dims[1] != param_.headNum) {
364	        ATB_LOG(ERROR) << GetLogPrefix() << "dim 1 of query(intensor0) and queryRope(intensor1) equal to headNum";
365	        return ERROR_INVALID_TENSOR_DIM;
366	    }
367	
368	    if (inTensorDesc.at(0).shape.dims[2] != INNER_DIM_512 ||             // 2: dim 2
369	        inTensorDesc.at(KVCACHE_INDEX).shape.dims[3] != INNER_DIM_512) { // 3: dim 3
370	        ATB_LOG(ERROR) << GetLogPrefix() << "head_size of query(intensor0) and kvCache(intensor2) should be 512";
371	        return ERROR_INVALID_TENSOR_DIM;
372	    }
373	    if (inTensorDesc.at(1).shape.dims[2] != INNER_DIM_64 ||                  // 2: dim 2
374	        inTensorDesc.at(KVCACHE_ROPE_INDEX).shape.dims[3] != INNER_DIM_64) { // 3: dim 3
375	        ATB_LOG(ERROR) << GetLogPrefix() << "head_size of queryRope(intensor1) and kvCacheRope(intensor3) should be 64";
376	        return ERROR_INVALID_TENSOR_DIM;
377	    }
378	    return NO_ERROR;
379	}
