381	Status MultiLatentAttentionOperation::QKVDimCheckNz(const SVector<TensorDesc> &inTensorDesc) const
382	{
383	    int64_t numTokens = inTensorDesc.at(0).shape.dims[0];
384	    int64_t numBlocks = inTensorDesc.at(KVCACHE_INDEX).shape.dims[0];
385	    int64_t blockSize = inTensorDesc.at(KVCACHE_INDEX).shape.dims[2]; // 2: dim 2
386	    if (blockSize != DECODER_BLOCK_SIZE) { // decoder blockSize
387	        ATB_LOG(ERROR) << GetLogPrefix() << "decoder blockSize should be " << DECODER_BLOCK_SIZE << ", but got "
388	                       << blockSize;
389	        return ERROR_INVALID_TENSOR_DIM;
390	    }
391	    if (inTensorDesc.at(1).shape.dims[0] != numTokens) {
392	        ATB_LOG(ERROR) << GetLogPrefix() << "dim 0 of query(intensor0) and queryRope(intensor1) should be same";
393	        return ERROR_INVALID_TENSOR_DIM;
394	    }
395	    if (inTensorDesc.at(KVCACHE_ROPE_INDEX).shape.dims[0] != numBlocks ||
396	        inTensorDesc.at(KVCACHE_ROPE_INDEX).shape.dims[2] != blockSize) { // 2: dim 2
397	        ATB_LOG(ERROR) << GetLogPrefix()
398	                       << "dim 0 and dim 2 of kvCache(intensor2) and kvCacheRope(intensor3) should be same";
399	        return ERROR_INVALID_TENSOR_DIM;
400	    }
401	    if (inTensorDesc.at(KVCACHE_INDEX).shape.dims[3] != NZ_ALIGN_16 ||      // 3: dim 3
402	        inTensorDesc.at(KVCACHE_ROPE_INDEX).shape.dims[3] != NZ_ALIGN_16) { // 3: dim 3
403	        ATB_LOG(ERROR) << GetLogPrefix() << "dim 3 of kvCache(intensor2) and kvCacheRope(intensor3) should be 16";
404	        return ERROR_INVALID_TENSOR_DIM;
405	    }
406	
407	    if (inTensorDesc.at(0).shape.dims[1] != param_.headNum || inTensorDesc.at(1).shape.dims[1] != param_.headNum) {
408	        ATB_LOG(ERROR) << GetLogPrefix() << "dim 1 of query(intensor0) and queryRope(intensor1) equal to headNum";
409	        return ERROR_INVALID_TENSOR_DIM;
410	    }
411	
412	    if (inTensorDesc.at(0).shape.dims[2] != INNER_DIM_512 ||            // 2: dim 2
413	        inTensorDesc.at(KVCACHE_INDEX).shape.dims[1] != INNER_DIM_32) { // 1: dim 1
414	        ATB_LOG(ERROR) << GetLogPrefix()
415	                       << "head_size of query(intensor0) should be 512, dim 1 of kvCache(intensor2) should be 32";
416	        return ERROR_INVALID_TENSOR_DIM;
417	    }
418	    if (inTensorDesc.at(1).shape.dims[2] != INNER_DIM_64 ||                 // 2: dim 2
419	        inTensorDesc.at(KVCACHE_ROPE_INDEX).shape.dims[1] != INNER_DIM_4) { // 1: dim 1
420	        ATB_LOG(ERROR) << GetLogPrefix()
421	                       << "head_size of queryRope(intensor1) should be 64, dim 1 of kvCacheRope(intensor3) should be 4";
422	        return ERROR_INVALID_TENSOR_DIM;
423	    }
424	    return NO_ERROR;
425	}
