427	Status MultiLatentAttentionOperation::QKVDimCheckInt8Nz(const SVector<TensorDesc> &inTensorDesc) const
428	{
429	    int64_t numTokens = inTensorDesc.at(0).shape.dims[0];
430	    int64_t numBlocks = inTensorDesc.at(KVCACHE_INDEX).shape.dims[0];
431	    int64_t blockSize = inTensorDesc.at(KVCACHE_INDEX).shape.dims[2]; // 2: dim 2
432	    if (blockSize != DECODER_BLOCK_SIZE) { // decoder blockSize
433	        ATB_LOG(ERROR) << GetLogPrefix() << "decoder blockSize should be " << DECODER_BLOCK_SIZE << ", but got "
434	                       << blockSize;
435	        return ERROR_INVALID_TENSOR_DIM;
436	    }
437	    if (inTensorDesc.at(1).shape.dims[0] != numTokens) {
438	        ATB_LOG(ERROR) << GetLogPrefix() << "dim 0 of query(intensor0) and queryRope(intensor1) should be same";
439	        return ERROR_INVALID_TENSOR_DIM;
440	    }
441	    if (inTensorDesc.at(KVCACHE_ROPE_INDEX).shape.dims[0] != numBlocks ||
442	        inTensorDesc.at(KVCACHE_ROPE_INDEX).shape.dims[2] != blockSize) { // 2: dim 2
443	        ATB_LOG(ERROR) << GetLogPrefix()
444	                       << "dim 0 and dim 2 of kvCache(intensor2) and kvCacheRope(intensor3) should be same";
445	        return ERROR_INVALID_TENSOR_DIM;
446	    }
447	    if (inTensorDesc.at(KVCACHE_INDEX).shape.dims[3] != NZ_ALIGN_32 ||      // 3: dim 3
448	        inTensorDesc.at(KVCACHE_ROPE_INDEX).shape.dims[3] != NZ_ALIGN_16) { // 3: dim 3
449	        ATB_LOG(ERROR) << GetLogPrefix()
450	                       << "dim 3 of kvCache(intensor2) should be 32 and kvCacheRope(intensor3) should be 16";
451	        return ERROR_INVALID_TENSOR_DIM;
452	    }
453	
454	    if (inTensorDesc.at(0).shape.dims[1] != param_.headNum || inTensorDesc.at(1).shape.dims[1] != param_.headNum) {
455	        ATB_LOG(ERROR) << GetLogPrefix() << "dim 1 of query(intensor0) and queryRope(intensor1) equal to headNum";
456	        return ERROR_INVALID_TENSOR_DIM;
457	    }
458	
459	    if (inTensorDesc.at(0).shape.dims[2] != INNER_DIM_512 || // 2: dim 2
460	        inTensorDesc.at(KVCACHE_INDEX).shape.dims[1] != INNER_DIM_16) {
461	        ATB_LOG(ERROR) << GetLogPrefix()
462	                       << "head_size of query(intensor0) should be 512, dim 1 of kvCache(intensor2) should be 16";
463	        return ERROR_INVALID_TENSOR_DIM;
464	    }
465	    if (inTensorDesc.at(1).shape.dims[2] != INNER_DIM_64 || // 2: dim 2
466	        inTensorDesc.at(KVCACHE_ROPE_INDEX).shape.dims[1] != INNER_DIM_4) {
467	        ATB_LOG(ERROR) << GetLogPrefix()
468	                       << "head_size of queryRope(intensor1) should be 64, dim 1 of kvCacheRope(intensor3) should be 4";
469	        return ERROR_INVALID_TENSOR_DIM;
470	    }
471	    return NO_ERROR;
472	}
