474	Status MultiLatentAttentionOperation::DimCheckSpec(const SVector<TensorDesc> &inTensorDesc, size_t idx) const
475	{
476	    if (inTensorDesc.at(idx).shape.dimNum != 1) { // 1: 1 dim
477	        ATB_LOG(ERROR) << GetLogPrefix() << "invalid intensor dimNum";
478	        return ERROR_INVALID_TENSOR_DIM_NUM;
479	    }
480	    if (inTensorDesc.at(idx).shape.dims[0] != inTensorDesc.at(CONTEXTLENS_INDEX).shape.dims[0]) {
481	        ATB_LOG(ERROR) << GetLogPrefix() << "dim 0 of qSeqlen(intensor" << idx
482	                       << ") should be equal to dim0 of contextLens(intensor5)";
483	        return ERROR_INVALID_TENSOR_DIM;
484	    }
485	    return NO_ERROR;
486	}
487	
488	Status MultiLatentAttentionOperation::DimCheckInt8Nz(const SVector<TensorDesc> &inTensorDesc, size_t idx) const
489	{
490	    if (inTensorDesc.at(idx).shape.dimNum != 1 || inTensorDesc.at(idx + 1).shape.dimNum != 1) { // 1: 1 dim
491	        ATB_LOG(ERROR) << GetLogPrefix() << "invalid intensor dimNum";
492	        return ERROR_INVALID_TENSOR_DIM_NUM;
493	    }
494	    if (inTensorDesc.at(idx).shape.dims[0] != param_.headNum) {
495	        ATB_LOG(ERROR) << GetLogPrefix() << "dim 0 of of qkDescale(intensor" << idx
496	                       << ") should be equal to dim0 of headNum";
497	        return ERROR_INVALID_TENSOR_DIM;
498	    }
499	    if (inTensorDesc.at(idx + 1).shape.dims[0] != param_.headNum) {
500	        ATB_LOG(ERROR) << GetLogPrefix() << "dim 0 of of pvDescale(intensor" << (idx + 1)
501	                       << ") should be equal to dim0 of headNum";
502	        return ERROR_INVALID_TENSOR_DIM;
503	    }
504	    return NO_ERROR;
505	}
506	
507	Status MultiLatentAttentionOperation::DimCheckInt8NzLse(const SVector<TensorDesc> &inTensorDesc,
508	                                                        const SVector<TensorDesc> &outTensorDesc) const
509	{
510	    if (outTensorDesc.at(0).shape.dimNum != inTensorDesc.at(0).shape.dimNum) {
511	        ATB_LOG(ERROR) << GetLogPrefix() << "invalid outtensor dimNum";
512	        return ERROR_INVALID_TENSOR_DIM_NUM;
513	    }
514	    if ((outTensorDesc.at(0).shape.dims[0] != inTensorDesc.at(0).shape.dims[0]) ||
515	        (outTensorDesc.at(0).shape.dims[1] != inTensorDesc.at(0).shape.dims[1]) ||
516	        (outTensorDesc.at(0).shape.dims[DIM_2] != inTensorDesc.at(0).shape.dims[DIM_2])) {
517	        ATB_LOG(ERROR) << GetLogPrefix() << "invalid outtensor dims";
518	        return ERROR_INVALID_TENSOR_DIM;
519	    }
520	    if (outTensorDesc.at(1).shape.dimNum != inTensorDesc.at(0).shape.dimNum) {
521	        ATB_LOG(ERROR) << GetLogPrefix() << "invalid outtensor dimNum";
522	        return ERROR_INVALID_TENSOR_DIM_NUM;
523	    }
524	    if ((outTensorDesc.at(1).shape.dims[0] != inTensorDesc.at(0).shape.dims[0]) ||
525	        (outTensorDesc.at(1).shape.dims[1] != inTensorDesc.at(0).shape.dims[1]) ||
526	        (outTensorDesc.at(1).shape.dims[DIM_2] != 1)) {
527	        ATB_LOG(ERROR) << GetLogPrefix() << "invalid outtensor dims";
528	        return ERROR_INVALID_TENSOR_DIM;
529	    }
530	    return NO_ERROR;
531	}
532	
533	Status MultiLatentAttentionOperation::DimCheckMaskUseStatus(const SVector<TensorDesc> &inTensorDesc, size_t idx) const
534	{
535	    if (inTensorDesc.at(idx).shape.dimNum == 0) {
536	       return NO_ERROR;
537	    }
538	    if (inTensorDesc.at(idx).shape.dimNum != 1) { // 1: 1 dim, [batch]
539	        ATB_LOG(ERROR) << GetLogPrefix()
540	                       << "MTP tp1 or int8nz without tp1 need MaskUseStatus, but got invalid intensor dimNum at idx: "
541	                       << idx << ", expect 1 but got: " << inTensorDesc.at(idx).shape.dimNum;
542	        return ERROR_INVALID_TENSOR_DIM_NUM;
543	    }
544	    int64_t batch = inTensorDesc.at(CONTEXTLENS_INDEX).shape.dims[0];
545	    if (inTensorDesc.at(idx).shape.dims[0] != batch) {
546	        ATB_LOG(ERROR) << GetLogPrefix() << "dim 0 of maskUseStatus(intensor" << idx << "), "
547	                    << inTensorDesc.at(idx).shape.dims[0] << ", should be equal to dim0 of contextLens(intensor5), "
548	                    << batch;
549	        return ERROR_INVALID_TENSOR_DIM;
550	    }
551	    return NO_ERROR;
552	}
553	
554	Status MultiLatentAttentionOperation::DimCheckMTP(const SVector<TensorDesc> &inTensorDesc) const
555	{
556	    size_t idx = IN_TENSOR_6;
557	    if (param_.maskType != infer::MultiLatentAttentionParam::MaskType::UNDEFINED &&
558	        param_.maskType != infer::MultiLatentAttentionParam::MaskType::MASK_TYPE_CAUSAL_MASK) {
559	        ++idx; // 1: mask
560	    }
561	    Status st = DimCheckSpec(inTensorDesc, idx);
562	    if (st != NO_ERROR) {
563	        return st;
564	    }
565	    ++idx; // move to maskUseStatus
566	    if (param_.cacheMode == infer::MultiLatentAttentionParam::CacheMode::INT8_NZCACHE) {
567	        idx += 2; // 2: qDescale, kDescale
568	    }
569	    if (param_.maskUseStatusType ==
570	            infer::MultiLatentAttentionParam::MaskUseStatusType::MASK_USE_STATUS_TYPE_BATCH_MASK &&
571	        (param_.headNum == MTP_TP1_HEAD_NUM ||
572	         param_.cacheMode == infer::MultiLatentAttentionParam::CacheMode::INT8_NZCACHE)) {
573	        // MTP1场景下 tp1/非tp1且开启int8nz量化
574	        return DimCheckMaskUseStatus(inTensorDesc, idx);
575	    }
576	    return NO_ERROR;
577	}
578	
579	Status MultiLatentAttentionOperation::DimCheck(const SVector<TensorDesc> &inTensorDesc) const
580	{
581	    if (inTensorDesc.at(0).shape.dimNum != 3 ||                  // 0: query 3: 3 dims
582	        inTensorDesc.at(1).shape.dimNum != 3 ||                  // 1: queryRope 3: 3 dims
583	        inTensorDesc.at(KVCACHE_INDEX).shape.dimNum != 4 ||      // 4: 4 dims
584	        inTensorDesc.at(KVCACHE_ROPE_INDEX).shape.dimNum != 4 || // 4: 4 dims
585	        inTensorDesc.at(BLOCK_TABLES_INDEX).shape.dimNum != 2 || // 2: 2 dims
586	        inTensorDesc.at(CONTEXTLENS_INDEX).shape.dimNum != 1) {  // 1: 1 dim
587	        ATB_LOG(ERROR) << GetLogPrefix() << "invalid intensor dimNum";
588	        return ERROR_INVALID_TENSOR_DIM_NUM;
589	    }
590	    int64_t numTokens = inTensorDesc.at(0).shape.dims[0];
591	    int64_t batch = inTensorDesc.at(BLOCK_TABLES_INDEX).shape.dims[0];
592	    if (batch > MAX_BATCH_SIZE_8192) {
593	        ATB_LOG(ERROR) << GetLogPrefix() << "batch should be <= " << MAX_BATCH_SIZE_8192;
594	        return ERROR_INVALID_TENSOR_DIM;
595	    }
596	    if (param_.calcType == infer::MultiLatentAttentionParam::CalcType::CALC_TYPE_UNDEFINED && numTokens != batch) {
597	        ATB_LOG(ERROR) << GetLogPrefix() << "numTokens and batch should be same in decoder stage";
598	        return ERROR_INVALID_TENSOR_DIM;
599	    }
600	    if (inTensorDesc.at(CONTEXTLENS_INDEX).shape.dims[0] != batch) {
601	        ATB_LOG(ERROR) << GetLogPrefix()
602	                       << "dim 0 of block_tables(intensor4) and contextLens(intensor5) should be same";
603	        return ERROR_INVALID_TENSOR_DIM;
604	    }
605	    Status st = NO_ERROR;
606	    if (param_.cacheMode == infer::MultiLatentAttentionParam::CacheMode::KROPE_CTKV) {
607	        st = QKVDimCheck(inTensorDesc);
608	    }
609	    else if (param_.cacheMode == infer::MultiLatentAttentionParam::CacheMode::INT8_NZCACHE) {
610	        st = QKVDimCheckInt8Nz(inTensorDesc);
611	    }
612	    else if (param_.cacheMode == infer::MultiLatentAttentionParam::CacheMode::NZCACHE) {
613	        st = QKVDimCheckNz(inTensorDesc);
614	    }
615	    if (st != NO_ERROR) {
616	        return st;
617	    }
618	    if (param_.calcType == infer::MultiLatentAttentionParam::CalcType::CALC_TYPE_SPEC ||
619	        param_.calcType == infer::MultiLatentAttentionParam::CalcType::CALC_TYPE_SPEC_AND_RING) {
620	        // mtp
621	        st = DimCheckMTP(inTensorDesc);
622	    }
623	    if (st != NO_ERROR) {
624	        return st;
625	    }
626	    if ((param_.calcType == infer::MultiLatentAttentionParam::CalcType::CALC_TYPE_RING ||
627	         param_.calcType == infer::MultiLatentAttentionParam::CalcType::CALC_TYPE_SPEC_AND_RING) &&
628	        param_.maskType == infer::MultiLatentAttentionParam::MaskType::UNDEFINED &&
629	        param_.cacheMode == infer::MultiLatentAttentionParam::CacheMode::INT8_NZCACHE) {
630	        // ring
631	        size_t idx = IN_TENSOR_6;
632	        if (param_.calcType == infer::MultiLatentAttentionParam::CalcType::CALC_TYPE_SPEC_AND_RING) {
633	            ++idx; // 1: qSeqlen
634	        }
635	        st = DimCheckInt8Nz(inTensorDesc, idx);
636	    }
637	    return st;
638	}
639	
640	Status MultiLatentAttentionOperation::InTensorDimCheckPrefill(const SVector<TensorDesc> &inTensorDesc) const
641	{
642	    if ((inTensorDesc.at(IN_TENSOR_0).shape.dimNum != 2 &&  // 0: query 2:   2 dims
643	         inTensorDesc.at(IN_TENSOR_0).shape.dimNum != 3) || // 0: query 3:   3 dims
644	        (inTensorDesc.at(IN_TENSOR_1).shape.dimNum !=       // 1: queryRope
645	         inTensorDesc.at(IN_TENSOR_0).shape.dimNum) ||      // 0: query
646	        inTensorDesc.at(IN_TENSOR_2).shape.dimNum != 3 ||   // 2: key        3: 3 dims
647	        inTensorDesc.at(IN_TENSOR_3).shape.dimNum != 3 ||   // 3: keyRope    3: 3 dims
648	        inTensorDesc.at(IN_TENSOR_4).shape.dimNum != 3 ||   // 4: value      3: 3 dims
649	        inTensorDesc.at(IN_TENSOR_5).shape.dimNum != 1 ||   // 5: qSeqLen    1: 1 dims
650	        inTensorDesc.at(IN_TENSOR_6).shape.dimNum != 1 ||   // 6: kvSeqLen   1: 1 dims
651	        (param_.maskType == infer::MultiLatentAttentionParam::MaskType::MASK_TYPE_MASK_FREE &&
652	         (inTensorDesc.at(IN_TENSOR_7).shape.dimNum != 2 &&
653	          inTensorDesc.at(IN_TENSOR_7).shape.dimNum != 3))) { // 7: mask       2: 2 dims, 3: 3 dims
654	        ATB_LOG(ERROR) << GetLogPrefix() << "invalid intensor dimNum";
655	        return ERROR_INVALID_TENSOR_DIM_NUM;
656	    }
657	    if (inTensorDesc.at(IN_TENSOR_5).shape.dims[0] > MAX_BATCH_SIZE_8192) {
658	        ATB_LOG(ERROR) << GetLogPrefix() << "batch should be <= " << MAX_BATCH_SIZE_8192
659	                       << ", batch = " << inTensorDesc.at(IN_TENSOR_5).shape.dims[0];
660	        return ERROR_INVALID_TENSOR_DIM;
661	    }
662	    if (inTensorDesc.at(IN_TENSOR_5).shape.dims[0] != inTensorDesc.at(IN_TENSOR_6).shape.dims[0]) {
663	        ATB_LOG(ERROR) << GetLogPrefix()
664	                       << "dim 0 of qSeqLen(intensor5) and dim 0 of kvSeqLen(intensor6) shouble be same";
665	        return ERROR_INVALID_TENSOR_DIM;
666	    }
667	    Status st = QKVDimCheckPrefill(inTensorDesc);
668	    if (st != NO_ERROR) {
669	        return st;
670	    }
671	    if (param_.maskType == infer::MultiLatentAttentionParam::MaskType::MASK_TYPE_MASK_FREE) {
672	        if (inTensorDesc.at(IN_TENSOR_7).shape.dimNum == 2) {
673	            if (inTensorDesc.at(IN_TENSOR_7).shape.dims[0] != 512) { // 512: 压缩mask的规格
674	                ATB_LOG(ERROR) << GetLogPrefix() << "dim 0 of mask(intensor7) should be equal to 512";
675	                return ERROR_INVALID_TENSOR_DIM;
676	            }
677	            if (inTensorDesc.at(IN_TENSOR_7).shape.dims[1] != 512) { // 512: 压缩mask的规格
678	                ATB_LOG(ERROR) << GetLogPrefix() << "dim 1 of mask(intensor7) should be equal to 512";
679	                return ERROR_INVALID_TENSOR_DIM;
680	            }
681	        }
682	    }
683	    return NO_ERROR;
684	}
685	
686	Status MultiLatentAttentionOperation::QDimCheckPrefill(const SVector<TensorDesc> &inTensorDesc) const
687	{
688	    int64_t numTokens = inTensorDesc.at(IN_TENSOR_0).shape.dims[0];
689	    if (inTensorDesc.at(IN_TENSOR_0).shape.dimNum == 2) { // 2: 2 dim
690	        if (inTensorDesc.at(IN_TENSOR_0).shape.dims[1] != param_.headNum * EM_BED_DIM_V) {
691	            ATB_LOG(ERROR) << GetLogPrefix() << "dim 1 of query(intensor0) should be equal to headNum * embeddimV";
692	            return ERROR_INVALID_TENSOR_DIM;
693	        }
694	    } else {
695	        if (inTensorDesc.at(IN_TENSOR_0).shape.dims[1] != param_.headNum) {
696	            ATB_LOG(ERROR) << GetLogPrefix() << "dim 1 of query(intensor0) should be equal to headNum ";
697	            return ERROR_INVALID_TENSOR_DIM;
698	        }
699	        if (inTensorDesc.at(IN_TENSOR_0).shape.dims[DIM_2] != EM_BED_DIM_V) {
700	            ATB_LOG(ERROR) << GetLogPrefix() << "dim 2 of query(intensor0) should be equal to embeddimV ";
701	            return ERROR_INVALID_TENSOR_DIM;
702	        }
703	    }
704	    if (inTensorDesc.at(IN_TENSOR_1).shape.dims[0] != numTokens) {
705	        ATB_LOG(ERROR) << GetLogPrefix() << "dim 0 of query(intensor0) and queryRope(intensor1) should be same";
706	        return ERROR_INVALID_TENSOR_DIM;
707	    }
708	    if (inTensorDesc.at(IN_TENSOR_1).shape.dimNum == 2) {                        // 2: 2 dim
709	        if (inTensorDesc.at(IN_TENSOR_1).shape.dims[1] != param_.headNum * 64) { // 64: embeddim - embeddimV
710	            ATB_LOG(ERROR) << GetLogPrefix() << "dim 1 of queryRope(intensor1)should be equal to headNum * 64";
711	            return ERROR_INVALID_TENSOR_DIM;
712	        }
713	    } else {
714	        if (inTensorDesc.at(IN_TENSOR_1).shape.dims[1] != param_.headNum) {
715	            ATB_LOG(ERROR) << GetLogPrefix() << "dim 1 of queryRope(intensor1)should be equal to headNum ";
716	            return ERROR_INVALID_TENSOR_DIM;
717	        }
718	        if (inTensorDesc.at(IN_TENSOR_1).shape.dims[DIM_2] != 64) { // 64: embeddim - embeddimV
719	            ATB_LOG(ERROR) << GetLogPrefix() << "dim 2 of queryRope(intensor1)should be equal to 64 ";
720	            return ERROR_INVALID_TENSOR_DIM;
721	        }
722	    }
723	    return NO_ERROR;
724	}
725	
726	Status MultiLatentAttentionOperation::KVDimCheckPrefill(const SVector<TensorDesc> &inTensorDesc) const
727	{
728	    if (param_.maskType != infer::MultiLatentAttentionParam::MaskType::MASK_TYPE_CAUSAL_MASK) {
729	        if ((inTensorDesc.at(IN_TENSOR_2).shape.dims[1] != param_.kvHeadNum ||
730	             inTensorDesc.at(IN_TENSOR_2).shape.dims[DIM_2] != EM_BED_DIM_V) &&
731	            (inTensorDesc.at(IN_TENSOR_2).shape.dims[0] != inTensorDesc.at(IN_TENSOR_5).shape.dims[0] ||
732	             inTensorDesc.at(IN_TENSOR_2).shape.dims[DIM_2] != param_.kvHeadNum * EM_BED_DIM_V)) {
733	            ATB_LOG(ERROR) << GetLogPrefix() << "key(intensor2) is invalid, only support [B*S,N,D] / [B,S,N*D]";
734	            return ERROR_INVALID_TENSOR_DIM;
735	        }
736	    } else {
737	        if (inTensorDesc.at(IN_TENSOR_2).shape.dims[0] != inTensorDesc.at(IN_TENSOR_5).shape.dims[0] ||
738	            inTensorDesc.at(IN_TENSOR_2).shape.dims[DIM_2] != param_.kvHeadNum * EM_BED_DIM_V) {
739	            ATB_LOG(ERROR) << GetLogPrefix() << "key(intensor2) is invalid, only support [B,S,N*D]";
740	            return ERROR_INVALID_TENSOR_DIM;
741	        }
742	    }
743	    if (inTensorDesc.at(IN_TENSOR_3).shape.dims[0] != inTensorDesc.at(IN_TENSOR_2).shape.dims[0]) {
744	        ATB_LOG(ERROR) << GetLogPrefix() << "dim 0 of keyRope(intensor3) and key(intensor2) should be same";
745	        return ERROR_INVALID_TENSOR_DIM;
746	    }
747	    if (inTensorDesc.at(IN_TENSOR_3).shape.dims[1] != inTensorDesc.at(IN_TENSOR_2).shape.dims[1]) {
748	        ATB_LOG(ERROR) << GetLogPrefix() << "dim 1 of keyRope(intensor3) and key(intensor2) should be same";
749	        return ERROR_INVALID_TENSOR_DIM;
750	    }
751	    if (inTensorDesc.at(IN_TENSOR_3).shape.dims[DIM_2] !=
752	        inTensorDesc.at(IN_TENSOR_2).shape.dims[DIM_2] / 2) { // 2: embiddim-embeddimV=64,embeddimV=128,128/64 = 2
753	        ATB_LOG(ERROR) << GetLogPrefix()
754	                       << "dim 2 of keyRope(intensor3) should be equal to dim 2 of key(intensor2) / 2";
755	        return ERROR_INVALID_TENSOR_DIM;
756	    }
757	    if (inTensorDesc.at(IN_TENSOR_4).shape.dims[0] != inTensorDesc.at(IN_TENSOR_2).shape.dims[0]) {
758	        ATB_LOG(ERROR) << GetLogPrefix() << "dim 0 of value(intensor4) and key(intensor2) should be same";
759	        return ERROR_INVALID_TENSOR_DIM;
760	    }
761	    if (inTensorDesc.at(IN_TENSOR_4).shape.dims[1] != inTensorDesc.at(IN_TENSOR_2).shape.dims[1]) {
762	        ATB_LOG(ERROR) << GetLogPrefix() << "dim 1 of value(intensor4) and key(intensor2) should be same";
763	        return ERROR_INVALID_TENSOR_DIM;
764	    }
765	    if (inTensorDesc.at(IN_TENSOR_4).shape.dims[DIM_2] != inTensorDesc.at(IN_TENSOR_2).shape.dims[DIM_2]) {
766	        ATB_LOG(ERROR) << GetLogPrefix() << "dim 2 of value(intensor4) and key(intensor2) should be same";
767	        return ERROR_INVALID_TENSOR_DIM;
768	    }
769	    return NO_ERROR;
770	}
771	
772	Status MultiLatentAttentionOperation::QKVDimCheckPrefill(const SVector<TensorDesc> &inTensorDesc) const
773	{
774	    Status st = NO_ERROR;
775	    st = QDimCheckPrefill(inTensorDesc);
776	    if (st != NO_ERROR) {
777	        return st;
778	    }
779	    st = KVDimCheckPrefill(inTensorDesc);
780	    if (st != NO_ERROR) {
781	        return st;
782	    }
783	    return NO_ERROR;
784	}
785	
786	std::shared_ptr<Runner> MultiLatentAttentionOperation::CreateRunner(Context &context) const
787	{
788	    (void)context;
789	    if (param_.calcType == infer::MultiLatentAttentionParam::CalcType::CALC_TYPE_PREFILL) {
790	        return std::make_shared<MultiLatentAttentionOpsRunnerPrefill>(param_);
791	    }
792	    return std::make_shared<MultiLatentAttentionOpsRunner>(param_);
793	}
794	
795	nlohmann::json MultiLatentAttentionOperation::GetParamJson() const
796	{
797	    return OpParamToJson(param_);
798	}
799	} // namespace atb
