53	template <> Status CreateOperation(const infer::MlaPreprocessParam &opParam, Operation **operation)
54	{
55	    if (operation == nullptr) {
56	        return ERROR_INVALID_PARAM;
57	    }
58	    ATB_LOG(INFO) << "CreateOperation with MlaPreprocessParam: " << OpParamToJson(opParam);
59	    if (!GetSingleton<Config>().Is910B()) {
60	        ATB_LOG(ERROR) << "only support Atlas 800I A2/A3 Inference Product";
61	        return ERROR_INVALID_PARAM;
62	    }
63	
64	    if (opParam.cacheMode > infer::MlaPreprocessParam::CacheMode::NZCACHE) {
65	        ATB_LOG(ERROR) << "invalid cacheMode";
66	        return ERROR_INVALID_PARAM;
67	    }
68	    if (opParam.quantMode == infer::MlaPreprocessParam::QuantMode::PER_TOKEN_QUANT_ASYMM ||
69	        opParam.quantMode == infer::MlaPreprocessParam::QuantMode::UNQUANT) {
70	        ATB_LOG(ERROR) << "invalid quantMode, doesn't support PER_TOKEN_ASYMM_QUANT and UNQUANT";
71	        return ERROR_INVALID_PARAM;
72	    }
73	    OP_PARAM_RSV_CHECK(opParam);
74	    Status status = MlaPreprocessAclnnRunner::LoadMethod();
75	    bool isAclnnFuncLoaded = false;
76	    if (status != NO_ERROR) {
77	        ATB_LOG(WARN) << "Load Aclnn functions failed, Generalized hiddenSize and skip rmsNormQuant are not supported!";
78	    } else {
79	        isAclnnFuncLoaded = true;
80	    }
81	    *operation = new (std::nothrow) MlaPreprocessOperation(opParam, isAclnnFuncLoaded);
82	    if (*operation == nullptr) {
83	        ATB_LOG(ERROR) << "failed to new MlaPreprocessOperation";
84	        return ERROR_OUT_OF_HOST_MEMORY;
85	    }
86	    return NO_ERROR;
87	}
