131	    int64_t headNum = inTensorDescs.at(WUK_INDEX).shape.dims[0];
132	    outTensorDescs.at(0) = inTensorDescs.at(0);
133	    outTensorDescs.at(0).shape.dimNum = 3;              // 3 : dimNum, [tokenNum, headNum, headDim]
134	    outTensorDescs.at(0).shape.dims[0] = tokenNum;      // 0 : dim 0
135	    outTensorDescs.at(0).shape.dims[1] = headNum;       // 1 : dim 1
136	    outTensorDescs.at(0).shape.dims[2] = INNER_DIM_576; // 2 : dim 2
137	    outTensorDescs.at(1) = inTensorDescs.at(KVCACHE_INDEX);
138	    if (isSplit) {
139	        outTensorDescs.at(0).shape.dims[2] = INNER_DIM_512; // 2 : dim 2
140	        outTensorDescs.at(QOUT1_INDEX) = outTensorDescs.at(0);
141	        outTensorDescs.at(QOUT1_INDEX).shape.dims[2] = INNER_DIM_64; // 2 : dim 2
142	        outTensorDescs.at(KVCACHEOUT1_INDEX) = inTensorDescs.at(KVCACHE_ROPE_INDEX);
143	    }
144	    if (isint8Nz) {
145	        outTensorDescs.at(0).shape.dims[2] = INNER_DIM_512; // 2 : dim 2
146	        outTensorDescs.at(QOUT1_INDEX) = outTensorDescs.at(0);
147	        outTensorDescs.at(QOUT1_INDEX).shape.dims[2] = INNER_DIM_64; // 2 : dim 2
148	        outTensorDescs.at(KVCACHEOUT1_INDEX) = inTensorDescs.at(KVCACHE_ROPE_INDEX);
149	        outTensorDescs.at(0).dtype = ACL_INT8;
150	    }
151	    if (isNz) {
152	        outTensorDescs.at(0).shape.dims[2] = INNER_DIM_512; // 2 : dim 2
153	        outTensorDescs.at(QOUT1_INDEX) = outTensorDescs.at(0);
154	        outTensorDescs.at(QOUT1_INDEX).shape.dims[2] = INNER_DIM_64; // 2 : dim 2
155	        outTensorDescs.at(KVCACHEOUT1_INDEX) = inTensorDescs.at(KVCACHE_ROPE_INDEX);
156	    }
157	    return NO_ERROR;
158	}
