160	Status MlaPreprocessOperation::InferShapeCheckImpl(const SVector<TensorDesc> &inTensorDescs) const
161	{
162	    Status st = DimCheck(inTensorDescs);
163	    if (st != NO_ERROR) {
164	        return st;
165	    }
166	    return NO_ERROR;
