169	Status MlaPreprocessOperation::OutTensorCheck(const SVector<Tensor> &inTensors, const SVector<Tensor> &outTensors) const
170	{
171	    int64_t tokenNum = inTensors.at(0).desc.shape.dims[0];
172	    int64_t headNum = inTensors.at(WUK_INDEX).desc.shape.dims[0];
173	    if (outTensors.at(0).desc.shape.dimNum != 3 || // 3 : qOut dimNum
174	        outTensors.at(1).desc.shape.dimNum != 4) { // 4 : kvCacheOut dimNum
175	        ATB_LOG(ERROR) << "outTensor0 dimNum : " << outTensors.at(0).desc.shape.dimNum << "expect 3"
176	                       << " outTensor1 dimNum : " << outTensors.at(1).desc.shape.dimNum << "expect 4";
177	        return ERROR_INVALID_TENSOR_DIM_NUM;
178	    }
179	    if (outTensors.at(0).desc.shape.dims[0] != tokenNum ||      // 0 : dim 0
180	        outTensors.at(0).desc.shape.dims[1] != headNum ||       // 1 : dim 1
181	        outTensors.at(0).desc.shape.dims[2] != INNER_DIM_576) { // 2 : dim 2
182	        ATB_LOG(ERROR) << "outTensor0 dims : [" << outTensors.at(0).desc.shape.dims[0] << ","
183	                       << outTensors.at(0).desc.shape.dims[1] << "," << outTensors.at(0).desc.shape.dims[2] // 2 : dim 2
184	                       << "], expect [tokenNum,headNum,576]";
185	        return ERROR_INVALID_TENSOR_DIM;
186	    }
187	    if (!TensorUtil::TensorDescEqual(inTensors.at(KVCACHE_INDEX).desc, outTensors.at(1).desc)) {
188	        ATB_LOG(ERROR) << "kvCacheIn and kvCacheOut have different Desc";
189	        return ERROR_INVALID_TENSOR_DIM;
190	    }
191	    return NO_ERROR;
192	}
193	
194	Status MlaPreprocessOperation::OutTensorCheckSplit(const SVector<Tensor> &inTensors,
195	                                                   const SVector<Tensor> &outTensors) const
196	{
197	    int64_t tokenNum = inTensors.at(0).desc.shape.dims[0];
198	    int64_t headNum = inTensors.at(WUK_INDEX).desc.shape.dims[0];
199	    if (outTensors.at(0).desc.shape.dimNum != 3 || // 3: qOut dimNum
200	        outTensors.at(1).desc.shape.dimNum != 4 || // 4: kvCacheOut dimNum
201	        outTensors.at(2).desc.shape.dimNum != 3 || // 2: dim2 3: qOut dimNum
202	        outTensors.at(3).desc.shape.dimNum != 4) { // 3: dim3 4: kvCacheOut dimNum
203	        ATB_LOG(ERROR) << "outTensor0 dimNum : " << outTensors.at(0).desc.shape.dimNum << "expect 3"
204	                       << " outTensor1 dimNum : " << outTensors.at(1).desc.shape.dimNum << "expect 4"
205	                       << " outTensor2 dimNum : " << outTensors.at(2).desc.shape.dimNum << "expect 3"  // 2: dim2
206	                       << " outTensor3 dimNum : " << outTensors.at(3).desc.shape.dimNum << "expect 4"; // 3: dim3
207	        return ERROR_INVALID_TENSOR_DIM_NUM;
208	    }
209	    if (outTensors.at(0).desc.shape.dims[0] != tokenNum ||      // 0: dim 0
210	        outTensors.at(0).desc.shape.dims[1] != headNum ||       // 1: dim 1
211	        outTensors.at(0).desc.shape.dims[2] != INNER_DIM_512) { // 2: dim 2
212	        ATB_LOG(ERROR) << "outTensor0 dims expect [tokenNum,headNum,512]";
213	        return ERROR_INVALID_TENSOR_DIM;
214	    }
215	    if (outTensors.at(1).desc.shape.dims[0] != inTensors.at(KVCACHE_INDEX).desc.shape.dims[0] || // 0: dim 0
216	        outTensors.at(1).desc.shape.dims[1] != inTensors.at(KVCACHE_INDEX).desc.shape.dims[1] || // 1: dim 1
217	        outTensors.at(1).desc.shape.dims[2] != 1 ||                                              // 2: dim 2
218	        outTensors.at(1).desc.shape.dims[3] != INNER_DIM_512) {                                  // 3: dim 3
219	        ATB_LOG(ERROR) << "outTensor1 dims expect [blockNum,blockSize,1,512]";
220	        return ERROR_INVALID_TENSOR_DIM;
221	    }
222	    if (outTensors.at(2).desc.shape.dims[0] != tokenNum ||     // 2: tensor2 0 : dim 0
223	        outTensors.at(2).desc.shape.dims[1] != headNum ||      // 2: tensor2 1 : dim 1
224	        outTensors.at(2).desc.shape.dims[2] != INNER_DIM_64) { // 2: tensor2 2 : dim 2
225	        ATB_LOG(ERROR) << "outTensor2 dims expect [tokenNum,headNum,64]";
226	        return ERROR_INVALID_TENSOR_DIM;
227	    }
228	    if (outTensors.at(3).desc.shape.dims[0] != inTensors.at(KVCACHE_INDEX).desc.shape.dims[0] || // 3: tensor3 0: dim 0
229	        outTensors.at(3).desc.shape.dims[1] != inTensors.at(KVCACHE_INDEX).desc.shape.dims[1] || // 3: tensor3 1: dim 1
230	        outTensors.at(3).desc.shape.dims[2] != 1 ||                                              // 3: tensor3 2: dim 2
231	        outTensors.at(3).desc.shape.dims[3] != INNER_DIM_64) {                                   // 3: tensor3 3: dim 3
232	        ATB_LOG(ERROR) << "outTensor3 dims expect [blockNum,blockSize,1,64]";
233	        return ERROR_INVALID_TENSOR_DIM;
234	    }
235	    return NO_ERROR;
236	}
237	
238	Status MlaPreprocessOperation::SetupCheckImpl(const SVector<Tensor> &inTensors, const SVector<Tensor> &outTensors) const
239	{
240	    ATB_LOG(INFO) << GetLogPrefix() << "SetupCheckImpl";
241	    SVector<TensorDesc> inTensorDesc = {};
242	    OperationUtil::InTensorsToInTensorDescs(inTensors, inTensorDesc);
243	    Status st = DimCheck(inTensorDesc);
244	    if (st != NO_ERROR) {
245	        return st;
246	    }
247	    if (param_.cacheMode == infer::MlaPreprocessParam::CacheMode::KROPE_CTKV) {
248	        st = OutTensorCheckSplit(inTensors, outTensors);
249	    } else if (param_.cacheMode == infer::MlaPreprocessParam::CacheMode::INT8_NZCACHE) {
250	        st = NO_ERROR;
251	    } else if (param_.cacheMode == infer::MlaPreprocessParam::CacheMode::NZCACHE) {
252	        st = NO_ERROR;
253	    } else {
254	        st = OutTensorCheck(inTensors, outTensors);
255	    }
256	    if (st != NO_ERROR) {
257	        return st;
258	    }
259	    return NO_ERROR;
260	}
261	
262	Status MlaPreprocessOperation::TensorShapeCheck(const atb::SVector<atb::TensorDesc> &inTensorDesc,
263	                                                const std::vector<std::vector<int64_t>> &inTensorShapes) const
264	{
265	    ATB_LOG(INFO) << GetLogPrefix() << "TensorShapeCheck start";
266	    if (inTensorDesc.size() != inTensorShapes.size()) {
267	        ATB_LOG(ERROR) << "inTensor num is not equal to the expect num : " << inTensorShapes.size();
268	        return ERROR_INVALID_IN_TENSOR_NUM;
269	    }
270	    for (size_t i = 0; i < inTensorDesc.size(); i++) {
271	        ATB_LOG(INFO) << GetLogPrefix() << "TensorShapeCheck index [" << i << "]";
272	        if (inTensorShapes.at(i).size() == 0 || inTensorDesc.at(i).shape.dimNum == 0) {
273	            continue;
274	        }
275	        if (inTensorDesc.at(i).shape.dimNum != inTensorShapes.at(i).size()) {
276	            ATB_LOG(ERROR) << "inTensor" << i << " dimnum " << inTensorDesc[i].shape.dimNum
277	                           << " is not equal to the expect dimnum : " << inTensorShapes[i].size();
278	            return ERROR_INVALID_TENSOR_DIM_NUM;
279	        }
280	        for (size_t j = 0; j < inTensorDesc[i].shape.dimNum; j++) {
281	            if (inTensorShapes[i][j] != -1 && inTensorDesc.at(i).shape.dims[j] != inTensorShapes[i][j]) {
282	                ATB_LOG(ERROR) << "inTensor" << i << " dim" << j << " size:" << inTensorDesc.at(i).shape.dims[j]
283	                               << " is not equal to the expect dim size : " << inTensorShapes[i][j];
284	                return ERROR_INVALID_TENSOR_DIM;
285	            }
286	        }
287	    }
288	    ATB_LOG(INFO) << GetLogPrefix() << "TensorShapeCheck finished";
289	    return NO_ERROR;
290	}
291	
292	void MlaPreprocessOperation::ModifyInTensorShapeTable(const atb::SVector<atb::TensorDesc> &inTensorDesc,
293	                                                      const std::vector<std::vector<int64_t>> &inTensorShapes,
294	                                                      const int64_t headNum) const
295	{
296	    (void)inTensorDesc;
297	    (void)inTensorShapes;
298	    (void)headNum;
299	}
300	
301	Status MlaPreprocessOperation::DimCheck(const SVector<TensorDesc> &inTensorDesc) const
302	{
303	    ATB_LOG(INFO) << GetLogPrefix() << "DimCheck start";
304	    int64_t tokenNum = inTensorDesc.at(0).shape.dims[0];
305	    int64_t headNum = inTensorDesc.at(WUK_INDEX).shape.dims[0];
306	    if (tokenNum <= 0 || headNum <= 0) {
307	        ATB_LOG(ERROR) << "tokenNum and headNum should > 0";
308	        return ERROR_INVALID_TENSOR_DIM;
309	    }
310	    if (tokenNum > MAX_TOKEN_NUM) {
311	        ATB_LOG(ERROR) << "tokenNum should <= " << MAX_TOKEN_NUM;
312	        return ERROR_INVALID_TENSOR_DIM;
313	    }
314	    Status st = BlockSizeCheck(inTensorDesc);
315	    if (st != NO_ERROR) {
316	        return st;
317	    }
318	    st = CheckAclnnKernel(inTensorDesc);
319	    if (st != NO_ERROR) {
320	        return st;
321	    }
322	    st = HiddenSizeCheck(inTensorDesc);
323	    if (st != NO_ERROR) {
324	        return st;
325	    }
326	    std::vector<std::vector<int64_t>> inTensorShapes = {
327	        {},                        // input
328	        {},                        // gamma0
329	        {},                        // beta0
330	        {1},                       // quantScale0
331	        {1},                       // quantOffset0
332	        {},                        // wdqkv
333	        {INNER_DIM_2112},          // deScale0
334	        {},                        // bias0
335	        {INNER_DIM_1536},          // gamma1
336	        {INNER_DIM_1536},          // beta1
337	        {1},                       // quantScale1
338	        {1},                       // quantOffset1
339	        {},                        // wuq
340	        {headNum * INNER_DIM_192}, // deScale1
341	        {},                        // bias1
342	        {INNER_DIM_512},           // gamma2
343	        {tokenNum, INNER_DIM_64},  // cos
344	        {tokenNum, INNER_DIM_64},  // sin
345	        {},                        // wuk
346	        {},                        // ctkv
347	        {},                        // kRope
348	        {tokenNum},                // slotmapping
349	        {},                        // ctkvScale
350	        {},                        // qNopeScale
351	    };
352	    ModifyInTensorShapeTable(inTensorDesc, inTensorShapes, headNum);
353	    st = TensorShapeCheck(inTensorDesc, inTensorShapes);
354	    if (st != NO_ERROR) {
355	        return st;
356	    }
357	    ATB_LOG(INFO) << GetLogPrefix() << "DimCheck finished";
358	    return NO_ERROR;
359	}
360	
361	Status MlaPreprocessOperation::BlockSizeCheck(const SVector<TensorDesc> &inTensorDesc) const
362	{
363	    ATB_LOG(INFO) << GetLogPrefix() << "BlockSizeCheck start";
364	    bool isNz = (param_.cacheMode == infer::MlaPreprocessParam::CacheMode::INT8_NZCACHE ||
365	                 param_.cacheMode == infer::MlaPreprocessParam::CacheMode::NZCACHE);
366	    int64_t blockSize = isNz ? inTensorDesc.at(KVCACHE_INDEX).shape.dims[2] : // 2: blocksizeIdx
367	                               inTensorDesc.at(KVCACHE_INDEX).shape.dims[1];
368	    if (blockSize <= 0 || (blockSize > 128 && blockSize != 256)) { // 128 , 256 : blockSize ∈ [1, 128]∪{256}
369	        ATB_LOG(ERROR) << "blockSize should > 0 and <= 128 or == 256";
370	        return ERROR_INVALID_TENSOR_DIM;
371	    }
372	    if (isNz && blockSize != 128) { // 128: blocksize
373	        ATB_LOG(ERROR) << "blockSize should be 128 with INT8_NZCACHE or NZCACHE";
374	        return ERROR_INVALID_TENSOR_DIM;
375	    }
376	    ATB_LOG(INFO) << GetLogPrefix() << "BlockSizeCheck finished";
377	    return NO_ERROR;
378	}
379	
380	Status MlaPreprocessOperation::HiddenSizeCheck(const SVector<TensorDesc> &inTensorDesc) const
381	{
382	    if (inTensorDesc.at(INPUT_INDEX).shape.dimNum != 2) { // 2: input [tokenNum, hiddenSize]
383	        ATB_LOG(ERROR) << GetLogPrefix()
384	                       << "dimNum of input should be 2, but got: " << inTensorDesc.at(INPUT_INDEX).shape.dimNum;
385	        return ERROR_INVALID_TENSOR_DIM_NUM;
386	    }
387	    int64_t hiddenSize = inTensorDesc.at(INPUT_INDEX).shape.dims[1]; // 1: input hiddenSize index
388	    if (useAclnnKernel_) {
389	        if (hiddenSize < MIN_HIDDEN_SIZE || hiddenSize > MAX_HIDDEN_SIZE) {
390	            ATB_LOG(ERROR) << GetLogPrefix() << "expect hiddenSize of input to be in range [" << MIN_HIDDEN_SIZE << ","
391	                           << MAX_HIDDEN_SIZE << "], but got: " << hiddenSize;
392	            return ERROR_INVALID_TENSOR_DIM;
393	        }
394	    } else if (hiddenSize != INNER_DIM_7168) {
395	        ATB_LOG(ERROR) << GetLogPrefix() << "expect hiddenSize of input to be" << INNER_DIM_7168
396	                       << ", but got: " << hiddenSize;
397	        return ERROR_INVALID_TENSOR_DIM;
398	    }
399	    if (inTensorDesc.at(GAMMA0_INDEX).shape.dimNum != 1) { // 1: input [hiddenSize]
400	        ATB_LOG(ERROR) << GetLogPrefix()
401	                       << "dimNum of gamma0 should be 1, but got: " << inTensorDesc.at(GAMMA0_INDEX).shape.dimNum;
402	        return ERROR_INVALID_TENSOR_DIM_NUM;
403	    }
404	    if (inTensorDesc.at(GAMMA0_INDEX).shape.dims[0] != hiddenSize) {
405	        ATB_LOG(ERROR) << GetLogPrefix() << "hiddenSize of gamma0 should be the same as input's, " << hiddenSize
406	                       << ", but got: " << inTensorDesc.at(GAMMA0_INDEX).shape.dims[0]; // gamma0 hiddenSize index
407	        return ERROR_INVALID_TENSOR_DIM;
408	    }
409	    if (inTensorDesc.at(BETA0_INDEX).shape.dimNum != 1) { // 1: input [hiddenSize]
410	        ATB_LOG(ERROR) << GetLogPrefix()
411	                       << "dimNum of beta0 should be 1, but got: " << inTensorDesc.at(BETA0_INDEX).shape.dimNum;
412	        return ERROR_INVALID_TENSOR_DIM_NUM;
413	    }
414	    if (inTensorDesc.at(BETA0_INDEX).shape.dims[0] != hiddenSize) {
415	        ATB_LOG(ERROR) << GetLogPrefix() << "hiddenSize of beta0 should be the same as input's, " << hiddenSize
416	                       << ", but got: " << inTensorDesc.at(BETA0_INDEX).shape.dims[0]; // beta0 hiddenSize index
417	        return ERROR_INVALID_TENSOR_DIM;
418	    }
419	    return NO_ERROR;
420	}
421	
422	Status MlaPreprocessOperation::CheckAclnnKernel(const SVector<TensorDesc> &inTensorDesc) const
423	{
424	    ATB_LOG(INFO) << GetLogPrefix() << "CheckAclnnKernel start";
425	    // input's hiddenSize != 7168, generalize hiddenSize
426	    bool generalizedHiddenSize = inTensorDesc.at(INPUT_INDEX).shape.dims[1] != INNER_DIM_7168; // 1: hiddenSize
427	    // if wdqkv's dtype is the same as the input and is either float16/bf16, then do not do rmsNormQuant
428	    aclDataType inputDtype = inTensorDesc.at(INPUT_INDEX).dtype;
429	    doRmsNorm_ =
430	        !(inTensorDesc.at(WDQKV_INDEX).dtype == inputDtype && (inputDtype == ACL_FLOAT16 || inputDtype == ACL_BF16));
431	    if (!generalizedHiddenSize && doRmsNorm_) {
432	        ATB_LOG(INFO) << GetLogPrefix()
433	                      << "no need to use aclnn kernel for non-generalized hiddenSize and rmsNormQuant for input is on";
434	        useAclnnKernel_ = false;
435	        return NO_ERROR;
436	    }
437	    useAclnnKernel_ = true;
438	    if (param_.quantMode != infer::MlaPreprocessParam::QuantMode::PER_TENSOR_QUANT_ASYMM) {
439	        ATB_LOG(INFO) << GetLogPrefix()
440	                      << "aclnn mlaPreprocess only supports quantMode as PER_TENSOR_QUANT_ASYMM, but got: "
441	                      << param_.quantMode;
442	        return ERROR_INVALID_PARAM;
443	    }
444	    if (!isAclnnFuncLoaded_) {
445	        if (generalizedHiddenSize) {
446	            ATB_LOG(INFO) << GetLogPrefix()
447	                          << "Need to use aclnn kernel for generalized hiddenSize but load methods failed! Consider "
448	                             "change hiddenSize back to "
449	                          << INNER_DIM_7168 << " to use the atb kernel";
450	            return ERROR_INVALID_TENSOR_DIM_NUM;
451	        }
452	        if (!doRmsNorm_) {
453	            ATB_LOG(INFO) << GetLogPrefix()
454	                          << "Need to use aclnn kernel while skipping rmsNormQuant for input but load methods failed!";
455	            return ERROR_INVALID_TENSOR_DTYPE;
456	        }
457	    }
458	    ATB_LOG(INFO) << GetLogPrefix()
459	                  << "aclnn kernel is required and usable, generalizedHiddenSize: " << generalizedHiddenSize
460	                  << ", doRmsNorm: " << doRmsNorm_;
461	    return NO_ERROR;
462	}
463	
464	std::shared_ptr<Runner> MlaPreprocessOperation::CreateRunner(Context &context) const
465	{
466	    (void)context;
467	    if (useAclnnKernel_) {
468	        ATB_LOG(INFO) << GetLogPrefix() << "create MlaPreprocess AclnnRunner";
469	        bool doRmsNormParam = doRmsNorm_;
470	        useAclnnKernel_ = false;
471	        doRmsNorm_ = true;
472	        return std::make_shared<MlaPreprocessAclnnRunner>(param_, doRmsNormParam);
473	    }
474	
475	    ATB_LOG(INFO) << GetLogPrefix() << "create MlaPreprocess OpsRunner";
476	    if (param_.cacheMode == infer::MlaPreprocessParam::CacheMode::KVCACHE) {
477	        return std::make_shared<MlaPreprocessOpsRunner>(param_);
478	    }
479	    return std::make_shared<MlaPreprocessOpsRunnerSplit>(param_);
480	}
481	
482	nlohmann::json MlaPreprocessOperation::GetParamJson() const
483	{
484	    return OpParamToJson(param_);
485	}
486	} // namespace atb
