54	bool ParamCheck(const infer::RingMLAParam &opParam, ExternalError &extError)
55	{
56	    if (opParam.calcType != infer::RingMLAParam::CalcType::CALC_TYPE_DEFAULT &&
57	        opParam.calcType != infer::RingMLAParam::CalcType::CALC_TYPE_FIRST_RING) {
58	        extError.errorDesc = "Ring MLA expects calcType to be one of CALC_TYPE_DEFAULT, CALC_TYPE_FIRST_RING.";
59	        extError.errorData = OperationUtil::ConcatInfo("But got param.calcType = ", opParam.calcType);
60	        ATB_LOG(ERROR) << extError;
61	        return false;
62	    }
63	    if (opParam.headNum <= 0) {
64	        extError.errorDesc = "Ring MLA expects headNum to be greater than zero!";
65	        extError.errorData = OperationUtil::ConcatInfo("But got param.headNum = ", opParam.headNum);
66	        ATB_LOG(ERROR) << extError;
67	        return false;
68	    }
69	    if (opParam.kvHeadNum < 0) {
70	        extError.errorDesc = "Ring MLA expects kvHeadNum to be no less than zero!";
71	        extError.errorData = OperationUtil::ConcatInfo("But got param.kvHeadNum = ", opParam.kvHeadNum);
72	        return false;
73	    }
74	    if (opParam.kvHeadNum > 0 && opParam.headNum % opParam.kvHeadNum != 0) {
75	        extError.errorDesc = "Ring MLA expects headNum to be divisible by kvHeadNum.";
76	        extError.errorData = OperationUtil::ConcatInfo("But got param.headNum = ", opParam.headNum,
77	                                                       "param.kvHeadNum = ", opParam.kvHeadNum);
78	        ATB_LOG(ERROR) << extError;
79	        return false;
80	    }
81	    if (opParam.headNum < opParam.kvHeadNum) {
82	        extError.errorDesc = "Ring MLA expects headNum >= kvHeadNum";
83	        extError.errorData = OperationUtil::ConcatInfo("But got param.headNum = ", opParam.headNum,
84	                                                       "param.kvHeadNum = ", opParam.kvHeadNum);
85	        ATB_LOG(ERROR) << extError;
86	        return false;
87	    }
88	    if (opParam.maskType != infer::RingMLAParam::MaskType::NO_MASK &&
89	        opParam.maskType != infer::RingMLAParam::MaskType::MASK_TYPE_TRIU) {
90	        extError.errorDesc = "Ring MLA expects maskType as one of NO_MASK, MASK_TYPE_TRIU";
91	        extError.errorData = OperationUtil::ConcatInfo("But got param.maskType = ", opParam.maskType);
92	        ATB_LOG(ERROR) << extError;
93	        return false;
94	    }
95	    if (opParam.inputLayout != infer::TYPE_BSND) {
96	        extError.errorDesc = "Ring MLA only supports inputLayout as TYPE_BSND";
97	        extError.errorData = OperationUtil::ConcatInfo("But got param.inputLayout = ", opParam.inputLayout);
98	        ATB_LOG(ERROR) << extError;
99	        return false;
100	    }
101	    if (opParam.kernelType != infer::RingMLAParam::KernelType::KERNELTYPE_HIGH_PRECISION) {
102	        extError.errorDesc = "Ring MLA only supports kernelType as KERNELTYPE_HIGH_PRECISION";
103	        extError.errorData = OperationUtil::ConcatInfo("But got param.kernelType = ", opParam.kernelType);
104	        ATB_LOG(ERROR) << extError;
105	        return false;
106	    }
107	    return true;
108	}
109	
110	template <> Status CreateOperation(const infer::RingMLAParam &opParam, Operation **operation)
111	{
112	    if (operation == nullptr) {
113	        return ERROR_INVALID_PARAM;
114	    }
115	    OP_PARAM_RSV_CHECK(opParam);
116	    ATB_LOG(INFO) << "CreateOperation RingMLAParam headNum: " << opParam.headNum << ", kvHeadNum: " << opParam.kvHeadNum
117	                  << ", qkScale: " << opParam.qkScale << ", calcType: " << opParam.calcType
118	                  << ", kernelType: " << opParam.kernelType << ", maskType: " << opParam.maskType
119	                  << ", inputLayout:" << opParam.inputLayout;
120	    ExternalError extError;
121	    extError.errorType = ERROR_INVALID_PARAM;
122	    extError.solutionDesc = "Please check the RingMLA op params.";
123	    if (!GetSingleton<Config>().Is910B()) {
124	        extError.errorDesc = "Ring MLA only support 800I A2/A3 inference product";
125	        ATB_LOG(ERROR) << extError;
126	        return ERROR_INVALID_PARAM;
127	    }
128	    if (!ParamCheck(opParam, extError)) {
129	        return extError.errorType;
130	    }
131	    *operation = new (std::nothrow) RingMLAOperation(opParam);
132	    if (*operation == nullptr) {
133	        ATB_LOG(ERROR) << "failed to new operation";
134	        return ERROR_OUT_OF_HOST_MEMORY;
135	    }
136	    return NO_ERROR;
137	}
138	
139	
140	RingMLAOperation::RingMLAOperation(const infer::RingMLAParam &opParam)
141	    : OperationBase("RingMLAOperation"), param_(opParam)
142	{
143	    std::string opKey = "RingMLAOperation";
144	    if (opParam.calcType == infer::RingMLAParam::CALC_TYPE_DEFAULT) { // CALC_TYPE_DEFAULT:  输入lse，o，输出 lse，o
145	        isInputSoftmaxLse_ = true;
146	        opKey += "InputSoftmaxLse";
147	    }
148	    ATB_LOG(INFO) << GetLogPrefix() << "Ring MLA created with key: " << opKey;
149	    operationIr_ = GetSingleton<AtbOperationIrCfg>().GetOperationIr(opKey);
150	}
151	
152	
153	RingMLAOperation::~RingMLAOperation() {}
154	
155	uint32_t RingMLAOperation::GetInputNum() const
156	{
157	    if (isInputSoftmaxLse_) {
158	        return BASE_IN_TENSOR_NUM + RING_OPTIONAL_IN_TENSOR_NUM;
159	    }
160	    return BASE_IN_TENSOR_NUM;
161	}
162	
163	uint32_t RingMLAOperation::GetOutputNum() const
164	{
165	    return BASE_OUT_TENSOR_NUM;
166	}
