168	bool RingMLAOperation::DimNumCheck(const SVector<TensorDesc> &inTensorDescs, ExternalError &extError) const
169	{
170	    // IR: query1, query2, key1, key2, value, mask, (prevLse), (prevOut)
171	    for (int i = 0; i < 5; ++i) {                              // 5: query1, query2, key1, key2, value
172	        if (inTensorDescs.at(i).shape.dimNum != QKV_DIM_NUM) { // QKV_DIM_NUM: [nTokens, headNum, headSize]
173	            extError.errorDesc = OperationUtil::ConcatInfo("DimNum of inTensors[", i, "] should be ", QKV_DIM_NUM);
174	            extError.errorData =
175	                OperationUtil::ConcatInfo(", but got inTensors[", i, "] dimNum: ", inTensorDescs.at(i).shape.dimNum);
176	            ATB_LOG(ERROR) << GetLogPrefix() << extError;
177	            return false;
178	        }
179	    }
180	    if (param_.maskType != infer::RingMLAParam::MaskType::NO_MASK) {
181	        if (inTensorDescs.at(IN_MASK_INDEX).shape.dimNum != 2 && // 2: mask: [maxSeqLen, maxSeqLen]
182	            inTensorDescs.at(IN_MASK_INDEX).shape.dimNum != 3) { // 3: mask: [batch, maxSeqLen, maxSeqLen]
183	            extError.errorDesc = "dimNum of mask should be 2 or 3!";
184	            extError.errorData =
185	                OperationUtil::ConcatInfo(", but got mask dimNum: ", inTensorDescs.at(IN_MASK_INDEX).shape.dimNum);
186	            ATB_LOG(ERROR) << GetLogPrefix() << extError;
187	            return false;
188	        }
189	    }
190	
191	    if (inTensorDescs.at(IN_SEQLEN_INDEX).shape.dimNum != 1 && // 1: [batch]
192	        inTensorDescs.at(IN_SEQLEN_INDEX).shape.dimNum != 2) { // 2: [2, batch]
193	        extError.errorDesc = "dimNum of seqlen should be 1 or 2!";
194	        extError.errorData =
195	            OperationUtil::ConcatInfo(", but got seqlen dimNum: ", inTensorDescs.at(IN_SEQLEN_INDEX).shape.dimNum);
196	        ATB_LOG(ERROR) << GetLogPrefix() << extError;
197	        return false;
198	    }
199	    if (isInputSoftmaxLse_) {
200	        if (inTensorDescs.at(IN_PREV_OUT_INDEX).shape.dimNum != QKV_DIM_NUM) { // 3: [nTokens, headNum, headSize]
201	            extError.errorDesc = "dimNum of prevOut should be 3!";
202	            extError.errorData =
203	                OperationUtil::ConcatInfo("But got prevOut dimNum: ", inTensorDescs.at(IN_PREV_OUT_INDEX).shape.dimNum);
204	            ATB_LOG(ERROR) << GetLogPrefix() << extError;
205	            return false;
206	        }
207	        if (inTensorDescs.at(IN_PREV_LSE_INDEX).shape.dimNum != LSE_DIM_NUM) { // 2: [headNum, nTokens]
208	            extError.errorDesc = "dimNum of prevLse should be 2!";
209	            extError.errorData =
210	                OperationUtil::ConcatInfo("But got prevLse dimNum: ", inTensorDescs.at(IN_PREV_LSE_INDEX).shape.dimNum);
211	            ATB_LOG(ERROR) << GetLogPrefix() << extError;
212	            return false;
213	        }
214	    }
215	    return true;
216	}
217	
218	bool RingMLAOperation::QSplitDimCheck(const SVector<TensorDesc> &inTensorDescs, ExternalError &extError) const
219	{
220	    if (inTensorDescs.at(IN_QUERY_SPLIT1_INDEX).shape.dims[QKV_HEAD_SIZE_IDX] != QK_SPLIT1_HEAD_SIZE) {
221	        extError.errorDesc = OperationUtil::ConcatInfo("headSize of querySplit1 must be ", QK_SPLIT1_HEAD_SIZE);
222	        extError.errorData = OperationUtil::ConcatInfo(
223	            "But got querySplit1[2] headSize: ", inTensorDescs.at(IN_QUERY_SPLIT1_INDEX).shape.dims[QKV_HEAD_SIZE_IDX]);
224	        ATB_LOG(ERROR) << GetLogPrefix() << extError;
225	        return false;
226	    }
227	    if (inTensorDescs.at(IN_QUERY_SPLIT2_INDEX).shape.dims[QKV_HEAD_SIZE_IDX] != QK_SPLIT2_HEAD_SIZE) {
228	        extError.errorDesc = OperationUtil::ConcatInfo("headSize of querySplit2 must be ", QK_SPLIT2_HEAD_SIZE);
229	        extError.errorData = OperationUtil::ConcatInfo(
230	            "But got querySplit2[2] headSize: ", inTensorDescs.at(IN_QUERY_SPLIT2_INDEX).shape.dims[QKV_HEAD_SIZE_IDX]);
231	        ATB_LOG(ERROR) << GetLogPrefix() << extError;
232	        return false;
233	    }
234	    int64_t qNTokens = inTensorDescs.at(IN_QUERY_SPLIT1_INDEX).shape.dims[QKV_N_TOKENS_IDX];
235	    if (inTensorDescs.at(IN_QUERY_SPLIT2_INDEX).shape.dims[QKV_N_TOKENS_IDX] != qNTokens) {
236	        extError.errorDesc = "querySplit1[0] nTokens must be same as querySplit2[0] nTokens.";
237	        extError.errorData = OperationUtil::ConcatInfo(
238	            "But got querySplit1[0] nTkens: ", qNTokens,
239	            ", querySplit2[0] nTkens: ", inTensorDescs.at(IN_QUERY_SPLIT2_INDEX).shape.dims[QKV_N_TOKENS_IDX]);
240	        ATB_LOG(ERROR) << GetLogPrefix() << extError;
241	        return false;
242	    }
243	    int64_t qHeadNum = inTensorDescs.at(IN_QUERY_SPLIT1_INDEX).shape.dims[QKV_HEAD_NUM_IDX];
244	    if (inTensorDescs.at(IN_QUERY_SPLIT2_INDEX).shape.dims[QKV_HEAD_NUM_IDX] != qHeadNum) {
245	        extError.errorDesc = "querySplit1[1] must be same as querySplit2[1].";
246	        extError.errorData = OperationUtil::ConcatInfo(
247	            "But got querySplit1[1] headNum: ", qHeadNum,
248	            ", querySplit2[1] headNum: ", inTensorDescs.at(IN_QUERY_SPLIT2_INDEX).shape.dims[QKV_HEAD_NUM_IDX]);
249	        ATB_LOG(ERROR) << GetLogPrefix() << extError;
250	        return false;
251	    }
252	    return true;
253	}
254	
255	bool RingMLAOperation::KSplitDimCheck(const SVector<TensorDesc> &inTensorDescs, ExternalError &extError) const
256	{
257	    if (inTensorDescs.at(IN_KEY_SPLIT1_INDEX).shape.dims[QKV_HEAD_SIZE_IDX] != QK_SPLIT1_HEAD_SIZE) {
258	        extError.errorDesc = OperationUtil::ConcatInfo("headSize of keySplit1 must be ", QK_SPLIT1_HEAD_SIZE);
259	        extError.errorData = OperationUtil::ConcatInfo(
260	            "But got keySplit1[2] headSize: ", inTensorDescs.at(IN_KEY_SPLIT1_INDEX).shape.dims[QKV_HEAD_SIZE_IDX]);
261	        ATB_LOG(ERROR) << GetLogPrefix() << extError;
262	        return false;
263	    }
264	    if (inTensorDescs.at(IN_KEY_SPLIT2_INDEX).shape.dims[QKV_HEAD_SIZE_IDX] != QK_SPLIT2_HEAD_SIZE) {
265	        extError.errorDesc = OperationUtil::ConcatInfo("headSize of keySplit1 must be ", QK_SPLIT2_HEAD_SIZE);
266	        extError.errorData = OperationUtil::ConcatInfo(
267	            "But got keySplit1[2] headSize: ", inTensorDescs.at(IN_KEY_SPLIT1_INDEX).shape.dims[QKV_HEAD_SIZE_IDX]);
268	        ATB_LOG(ERROR) << GetLogPrefix() << extError;
269	        return false;
270	    }
271	    int64_t kvNTokens = inTensorDescs.at(IN_KEY_SPLIT1_INDEX).shape.dims[QKV_N_TOKENS_IDX];
272	    if (inTensorDescs.at(IN_KEY_SPLIT2_INDEX).shape.dims[QKV_N_TOKENS_IDX] != kvNTokens) {
273	        extError.errorDesc = "keySplit1[0] nTokens must be same as keySplit2[0] nTokens,";
274	        extError.errorData = OperationUtil::ConcatInfo(
275	            "But got keySplit1[0] nTokens: ", kvNTokens,
276	            ", keySplit2[0] nTokens: ", inTensorDescs.at(IN_KEY_SPLIT2_INDEX).shape.dims[QKV_N_TOKENS_IDX]);
277	        ATB_LOG(ERROR) << GetLogPrefix() << extError;
278	        return false;
279	    }
280	    int64_t kvHeadNum = inTensorDescs.at(IN_KEY_SPLIT1_INDEX).shape.dims[QKV_HEAD_NUM_IDX];
281	    if (inTensorDescs.at(IN_KEY_SPLIT2_INDEX).shape.dims[QKV_HEAD_NUM_IDX] != kvHeadNum) {
282	        extError.errorDesc = "keySplit1[1] headNum must be same as keySplit2[1] headNum,";
283	        extError.errorData = OperationUtil::ConcatInfo(
284	            "But got keySplit1[1] headNum: ", kvHeadNum,
285	            ", keySplit2[1] headNum: ", inTensorDescs.at(IN_QUERY_SPLIT2_INDEX).shape.dims[QKV_HEAD_NUM_IDX]);
286	        ATB_LOG(ERROR) << GetLogPrefix() << extError;
287	        return false;
288	    }
289	    return true;
290	}
291	
292	Status RingMLAOperation::DimCheck(const SVector<TensorDesc> &inTensorDescs) const
293	{
294	    ExternalError extError;
295	    extError.errorType = ERROR_INVALID_TENSOR_DIM_NUM;
296	    extError.solutionDesc = "Please check the shape of inTensors.";
297	    if (!DimNumCheck(inTensorDescs, extError)) {
298	        return ERROR_INVALID_TENSOR_DIM_NUM;
299	    }
300	    // qkv shape: [q/kv nTokens, q/kv HeadNum, qk/v headSize]
301	    extError.errorType = ERROR_INVALID_TENSOR_DIM;
302	    extError.solutionDesc = "Please check the shape of querySplit1, querySplit2, keySplit1, keySplit2 and value.";
303	    if (!QSplitDimCheck(inTensorDescs, extError)) {
304	        return extError.errorType;
305	    }
306	    if (!KSplitDimCheck(inTensorDescs, extError)) {
307	        return extError.errorType;
308	    }
309	    int64_t kvHeadNum = inTensorDescs.at(IN_KEY_SPLIT1_INDEX).shape.dims[QKV_HEAD_NUM_IDX];
310	    if (inTensorDescs.at(IN_VALUE_INDEX).shape.dims[QKV_HEAD_NUM_IDX] != kvHeadNum) {
311	        extError.errorDesc = "headNum of key and value should be the same,";
312	        extError.errorData = OperationUtil::ConcatInfo("key headNum: ", kvHeadNum, ", value headNum: ",
313	                                                       inTensorDescs.at(IN_VALUE_INDEX).shape.dims[QKV_HEAD_NUM_IDX]);
314	        ATB_LOG(ERROR) << GetLogPrefix() << extError;
315	        return extError.errorType;
316	    }
317	    if (inTensorDescs.at(IN_VALUE_INDEX).shape.dims[QKV_HEAD_SIZE_IDX] != QK_SPLIT1_HEAD_SIZE) {
318	        extError.errorDesc = OperationUtil::ConcatInfo("headSize of value should be ", QK_SPLIT1_HEAD_SIZE);
319	        extError.errorData = OperationUtil::ConcatInfo("But got value headSize: ",
320	                                                       inTensorDescs.at(IN_VALUE_INDEX).shape.dims[QKV_HEAD_SIZE_IDX]);
321	        ATB_LOG(ERROR) << GetLogPrefix() << extError;
322	        return extError.errorType;
323	    }
324	    if (inTensorDescs.at(IN_MASK_INDEX).shape.dimNum == 3) { // 3: mask: [batch, maxSeqLen, maxSeqLen]
325	        // 1: seqlen shape: [batch]
326	        int64_t batch = inTensorDescs.at(IN_SEQLEN_INDEX).shape.dims[SEQLEN_BATCH_IDX];
327	        if (inTensorDescs.at(IN_SEQLEN_INDEX).shape.dimNum == 2) {      // 2: seqlen shape: [2, batch]
328	            if (inTensorDescs.at(IN_SEQLEN_INDEX).shape.dims[0] != 2) { // 2: seqlen shape: [2, batch]
329	                extError.errorDesc = "2D seqlen should have the first dim as 2.";
330	                extError.errorData = OperationUtil::ConcatInfo("But got seqlen dims[0] = ",
331	                                                               inTensorDescs.at(IN_SEQLEN_INDEX).shape.dims[0]);
332	                ATB_LOG(ERROR) << GetLogPrefix() << extError;
333	            }
334	            batch = inTensorDescs.at(IN_SEQLEN_INDEX).shape.dims[1];
335	        }
336	        if (inTensorDescs.at(IN_MASK_INDEX).shape.dims[0] != batch) {
337	            extError.errorDesc = "batch of seqlen and mask should be the same.";
338	            extError.errorData = OperationUtil::ConcatInfo(
339	                "seqlen batch: ", batch, ", mask batch: ", inTensorDescs.at(IN_MASK_INDEX).shape.dims[0]);
340	            ATB_LOG(ERROR) << GetLogPrefix() << extError;
341	            return extError.errorType;
342	        }
343	    }
344	    return NO_ERROR;
345	}
346	
347	bool RingMLAOperation::InputLseDimCheck(const SVector<TensorDesc> &inTensorDescs, ExternalError &extError) const
348	{
349	    int64_t qNTokens = inTensorDescs.at(IN_QUERY_SPLIT1_INDEX).shape.dims[QKV_N_TOKENS_IDX];
350	    if (inTensorDescs.at(IN_PREV_OUT_INDEX).shape.dims[QKV_N_TOKENS_IDX] != qNTokens) {
351	        extError.errorDesc = "nTokens of query and prevOut should be the same!";
352	        extError.errorData = OperationUtil::ConcatInfo(
353	            "But got query nTokens: ", qNTokens,
354	            ", prevOut nTokens: ", inTensorDescs.at(IN_PREV_OUT_INDEX).shape.dims[QKV_N_TOKENS_IDX]);
355	        ATB_LOG(ERROR) << GetLogPrefix() << extError;
356	        return false;
357	    }
358	    if (inTensorDescs.at(IN_PREV_LSE_INDEX).shape.dims[LSE_N_TOKENS_IDX] != qNTokens) {
359	        extError.errorDesc = "nTokens of query and prvLse should be the same!";
360	        extError.errorData = OperationUtil::ConcatInfo(
361	            "But got query nTokens: ", qNTokens,
362	            ", prevLse nTokens: ", inTensorDescs.at(IN_PREV_LSE_INDEX).shape.dims[LSE_N_TOKENS_IDX]);
363	        ATB_LOG(ERROR) << GetLogPrefix() << extError;
364	        return false;
365	    }
366	    int64_t headNum = inTensorDescs.at(IN_QUERY_SPLIT1_INDEX).shape.dims[QKV_HEAD_NUM_IDX];
367	    if (inTensorDescs.at(IN_PREV_OUT_INDEX).shape.dims[QKV_HEAD_NUM_IDX] != headNum) {
368	        extError.errorDesc = "headNum of query and prevOut should be the same!";
369	        extError.errorData = OperationUtil::ConcatInfo(
370	            "But got query headNum: ", headNum,
371	            ", prevOut headNum: ", inTensorDescs.at(IN_PREV_OUT_INDEX).shape.dims[QKV_HEAD_NUM_IDX]);
372	        ATB_LOG(ERROR) << GetLogPrefix() << extError;
373	        return false;
374	    }
375	    if (inTensorDescs.at(IN_PREV_LSE_INDEX).shape.dims[LSE_HEAD_NUM_IDX] != headNum) {
376	        extError.errorDesc = "headNum of query and prevLse should be the same!";
377	        extError.errorData = OperationUtil::ConcatInfo(
378	            "But got query headNum: ", headNum,
379	            ", prevLse headNum: ", inTensorDescs.at(IN_PREV_LSE_INDEX).shape.dims[LSE_HEAD_NUM_IDX]);
380	        ATB_LOG(ERROR) << GetLogPrefix() << extError;
381	        return false;
382	    }
383	    int64_t headSizeV = inTensorDescs.at(IN_VALUE_INDEX).shape.dims[QKV_HEAD_SIZE_IDX];
384	    if (inTensorDescs.at(IN_PREV_OUT_INDEX).shape.dims[QKV_HEAD_SIZE_IDX] != headSizeV) {
385	        extError.errorDesc = "headSize of value and prevOut should be the same!";
386	        extError.errorData = OperationUtil::ConcatInfo(
387	            "But got value headSize: ", headSizeV,
388	            ", prevOut headSize: ", inTensorDescs.at(IN_PREV_OUT_INDEX).shape.dims[QKV_HEAD_SIZE_IDX]);
389	        ATB_LOG(ERROR) << GetLogPrefix() << extError;
390	        return false;
391	    }
392	    return true;
393	}
394	
395	Status RingMLAOperation::InferShapeCheckImpl(const SVector<TensorDesc> &inTensorDescs) const
396	{
397	    Status st = DimCheck(inTensorDescs);
398	    if (st != NO_ERROR) {
399	        return st;
400	    }
401	    if (isInputSoftmaxLse_) {
402	        ExternalError extError;
403	        extError.errorType = ERROR_INVALID_TENSOR_DIM;
404	        extError.solutionDesc = "Please check the shape of inTensors: query, value, prevOut and prevLse.";
405	        if (!InputLseDimCheck(inTensorDescs, extError)) {
406	            return extError.errorType;
407	        }
408	    }
409	    return NO_ERROR;
410	}
411	
412	Status RingMLAOperation::InferShapeImpl(const SVector<TensorDesc> &inTensorDescs,
413	                                        SVector<TensorDesc> &outTensorDescs) const
414	{
415	    outTensorDescs.at(OUT_PREV_OUT_INDEX) = inTensorDescs.at(IN_QUERY_SPLIT1_INDEX); // 0: output
416	    outTensorDescs.at(OUT_PREV_OUT_INDEX).shape.dims[QKV_HEAD_SIZE_IDX] =
417	        inTensorDescs.at(IN_VALUE_INDEX).shape.dims[QKV_HEAD_SIZE_IDX];
418	    if (isInputSoftmaxLse_) {
419	        // 输入lse，且输出lse，复用
420	        outTensorDescs.at(OUT_PREV_LSE_INDEX) = inTensorDescs.at(IN_PREV_LSE_INDEX); // 1: softmaxLse, 6: prevLse
421	        return NO_ERROR;
422	    }
423	    outTensorDescs.at(OUT_PREV_LSE_INDEX) = inTensorDescs.at(IN_QUERY_SPLIT1_INDEX); // 1: softmaxLse, 0: query
424	    outTensorDescs.at(OUT_PREV_LSE_INDEX).shape.dims[LSE_N_TOKENS_IDX] =
425	        inTensorDescs.at(IN_QUERY_SPLIT1_INDEX).shape.dims[QKV_N_TOKENS_IDX];
426	    outTensorDescs.at(OUT_PREV_LSE_INDEX).shape.dims[LSE_HEAD_NUM_IDX] =
427	        inTensorDescs.at(IN_QUERY_SPLIT1_INDEX).shape.dims[QKV_HEAD_NUM_IDX];
428	    // query: [nTokens, headNum, headSize] 删除headSize
429	    outTensorDescs.at(OUT_PREV_LSE_INDEX).shape.dims[QKV_HEAD_SIZE_IDX] = 0;
430	    outTensorDescs.at(OUT_PREV_LSE_INDEX).dtype = ACL_FLOAT;
431	    outTensorDescs.at(OUT_PREV_LSE_INDEX).shape.dimNum = LSE_DIM_NUM; // 1: softmaxLse 2: [nTokens, headNum]
432	    return NO_ERROR;
433	}
434	
435	Status RingMLAOperation::SetupCheckImpl(const SVector<Tensor> &inTensors, const SVector<Tensor> &outTensors) const
436	{
437	    Status st;
438	    SVector<TensorDesc> inTensorDescs = {};
439	    OperationUtil::InTensorsToInTensorDescs(inTensors, inTensorDescs);
440	    st = InferShapeCheckImpl(inTensorDescs);
441	    if (st != NO_ERROR) {
442	        return st;
443	    }
444	    SVector<TensorDesc> outTensorDescs = {};
445	    OperationUtil::InTensorsToInTensorDescs(outTensors, outTensorDescs);
446	    SVector<TensorDesc> targetOutTensorDescs = {};
447	    targetOutTensorDescs.reserve(BASE_OUT_TENSOR_NUM);
448	    targetOutTensorDescs.resize(BASE_OUT_TENSOR_NUM);
449	    InferShapeImpl(inTensorDescs, targetOutTensorDescs);
450	    ExternalError extError;
451	    extError.errorType = ERROR_INVALID_TENSOR_DIM;
452	    extError.solutionDesc = "Please check the shape of outTensor.";
453	    std::stringstream ss;
454	    for (size_t i = 0; i < BASE_OUT_TENSOR_NUM; ++i) {
455	        if (!TensorUtil::TensorDescEqual(outTensorDescs.at(i), targetOutTensorDescs.at(i))) {
456	            extError.errorDesc = OperationUtil::ConcatInfo("Invalid outTensor shape at outTensors[", i, "].");
457	            ss.str("");
458	            ss.clear();
459	            ss << "Target outTensor shape: [";
460	            int32_t dimNum = static_cast<int32_t>(targetOutTensorDescs.at(i).shape.dimNum);
461	            for (int32_t j = 0; j < dimNum - 1; ++j) {
462	                ss << targetOutTensorDescs.at(i).shape.dims[j] << ", ";
463	            }
464	            ss << targetOutTensorDescs.at(i).shape.dims[dimNum - 1] << "], ";
465	            ss << "but got outTensor shape: [";
466	            dimNum = static_cast<int32_t>(outTensorDescs.at(i).shape.dimNum);
467	            for (int32_t j = 0; j < dimNum - 1; ++j) {
468	                ss << outTensorDescs.at(i).shape.dims[j] << ", ";
469	            }
470	            ss << outTensorDescs.at(i).shape.dims[dimNum - 1] << "]. ";
471	            ss << "Target outTensor dtype: " << targetOutTensorDescs.at(i).dtype << ", ";
472	            ss << "outTensor dtype: " << outTensorDescs.at(i).dtype << ", ";
473	            ss << "Target outTensor format: " << targetOutTensorDescs.at(i).format << ", ";
474	            ss << "outTensor format: " << outTensorDescs.at(i).format;
475	            extError.errorData = ss.str();
476	            ATB_LOG(ERROR) << GetLogPrefix() << extError;
477	            return ERROR_INVALID_TENSOR_DIM;
478	        }
479	    }
480	    return NO_ERROR;
481	}
